INSERT INTO questions (category, difficulty, question_text, correct_answer, wrong_answers, language, is_active, explanation) VALUES
('nature', 1, 'Quel gaz les plantes produisent-elles lors de la photosynthèse ?', 'Oxygène', ARRAY['Dioxyde de carbone', 'Azote', 'Hydrogène'], 'fr', true, 'Les plantes absorbent le CO2 et produisent de l''oxygène grâce à la photosynthèse.'),
('nature', 1, 'Quel est le plus grand océan du monde ?', 'L''océan Pacifique', ARRAY['L''océan Atlantique', 'L''océan Indien', 'L''océan Arctique'], 'fr', true, 'L''océan Pacifique couvre environ un tiers de la surface de la Terre.'),
('nature', 1, 'Combien de saisons y a-t-il dans une année ?', '4', ARRAY['2', '3', '6'], 'fr', true, 'Les quatre saisons sont le printemps, l''été, l''automne et l''hiver.'),
('nature', 1, 'Comment appelle-t-on l''eau qui tombe du ciel ?', 'La pluie', ARRAY['La rosée', 'Le brouillard', 'La brume'], 'fr', true, 'La pluie est de l''eau qui se condense dans les nuages puis tombe sous forme de gouttes.'),
('nature', 1, 'Quelle est la couleur principale des feuilles au printemps ?', 'Vert', ARRAY['Rouge', 'Jaune', 'Marron'], 'fr', true, 'La chlorophylle donne aux feuilles leur couleur verte.'),
('nature', 1, 'Quel astre nous éclaire pendant la journée ?', 'Le Soleil', ARRAY['La Lune', 'Les étoiles', 'Vénus'], 'fr', true, 'Le Soleil est l''étoile la plus proche de la Terre.'),
('nature', 1, 'Comment s''appelle la couche de glace au sommet des montagnes ?', 'Un glacier', ARRAY['Un iceberg', 'Une banquise', 'Un névé'], 'fr', true, 'Les glaciers sont des masses de glace qui se forment en altitude.'),
('nature', 1, 'Quel phénomène naturel produit des éclairs ?', 'L''orage', ARRAY['Le cyclone', 'La tornade', 'Le tsunami'], 'fr', true, 'Les éclairs sont des décharges électriques qui se produisent pendant les orages.'),
('nature', 1, 'De quoi les arbres ont-ils besoin pour pousser ?', 'Eau, lumière et terre', ARRAY['Uniquement de l''eau', 'Uniquement du soleil', 'Du vent'], 'fr', true, 'Les arbres ont besoin d''eau, de lumière solaire et de nutriments du sol pour croître.'),
('nature', 1, 'Quel animal vit dans une ruche ?', 'L''abeille', ARRAY['La fourmi', 'La guêpe', 'Le papillon'], 'fr', true, 'Les abeilles vivent en colonies dans des ruches et produisent du miel.'),
('nature', 1, 'Comment appelle-t-on une montagne qui crache du feu ?', 'Un volcan', ARRAY['Un geyser', 'Un cratère', 'Un séisme'], 'fr', true, 'Un volcan est une ouverture dans la croûte terrestre d''où sort de la lave.'),
('nature', 1, 'Quelle partie de la plante absorbe l''eau dans le sol ?', 'Les racines', ARRAY['Les feuilles', 'La tige', 'Les fleurs'], 'fr', true, 'Les racines puisent l''eau et les nutriments du sol pour nourrir la plante.'),
('nature', 1, 'Quel est le fleuve le plus long de France ?', 'La Loire', ARRAY['La Seine', 'Le Rhône', 'La Garonne'], 'fr', true, 'La Loire mesure environ 1 012 km, ce qui en fait le plus long fleuve français.'),
('nature', 1, 'Qu''est-ce qui provoque les marées ?', 'La Lune', ARRAY['Le vent', 'Le Soleil uniquement', 'Les courants marins'], 'fr', true, 'L''attraction gravitationnelle de la Lune est la principale cause des marées.'),
('nature', 1, 'Comment appelle-t-on un arc multicolore dans le ciel après la pluie ?', 'Un arc-en-ciel', ARRAY['Une aurore boréale', 'Un halo', 'Un mirage'], 'fr', true, 'L''arc-en-ciel apparaît quand la lumière du soleil est réfractée par les gouttes de pluie.'),
('nature', 1, 'Quel type de forêt trouve-t-on près de l''équateur ?', 'La forêt tropicale', ARRAY['La forêt de conifères', 'La forêt tempérée', 'La toundra'], 'fr', true, 'Les forêts tropicales se trouvent près de l''équateur où il fait chaud et humide toute l''année.'),
('nature', 1, 'Quel est l''état de l''eau quand elle gèle ?', 'Solide', ARRAY['Liquide', 'Gazeux', 'Plasma'], 'fr', true, 'L''eau gèle à 0°C et passe de l''état liquide à l''état solide.'),
('nature', 1, 'Comment s''appelle le bébé de la grenouille ?', 'Le têtard', ARRAY['L''alevin', 'La larve', 'Le poussin'], 'fr', true, 'Le têtard est la forme larvaire de la grenouille, il vit dans l''eau avant de se transformer.'),
('nature', 1, 'Quelle est la plus haute montagne de France ?', 'Le Mont Blanc', ARRAY['Le Mont Ventoux', 'Le Puy de Dôme', 'La Meije'], 'fr', true, 'Le Mont Blanc culmine à 4 808 mètres dans les Alpes.'),
('nature', 1, 'Que produisent les abeilles ?', 'Du miel', ARRAY['Du lait', 'De la cire uniquement', 'Du sucre'], 'fr', true, 'Les abeilles produisent du miel à partir du nectar des fleurs.'),
('nature', 1, 'Comment appelle-t-on la saison où les feuilles tombent ?', 'L''automne', ARRAY['L''hiver', 'Le printemps', 'L''été'], 'fr', true, 'En automne, les feuilles changent de couleur et tombent des arbres à feuilles caduques.'),
('nature', 1, 'Quel gaz les humains rejettent-ils en respirant ?', 'Dioxyde de carbone', ARRAY['Oxygène', 'Azote', 'Hydrogène'], 'fr', true, 'Nous inspirons de l''oxygène et expirons du dioxyde de carbone (CO2).'),
('nature', 1, 'Comment s''appelle l''endroit où un cours d''eau se jette dans la mer ?', 'L''embouchure', ARRAY['La source', 'Le confluent', 'Le méandre'], 'fr', true, 'L''embouchure est l''endroit où un fleuve ou une rivière rejoint la mer ou l''océan.'),
('nature', 1, 'Quelle énergie provient du vent ?', 'L''énergie éolienne', ARRAY['L''énergie solaire', 'L''énergie hydraulique', 'L''énergie géothermique'], 'fr', true, 'L''énergie éolienne est produite par la force du vent grâce à des éoliennes.'),
('nature', 1, 'Quelle est la mer qui borde le sud de la France ?', 'La mer Méditerranée', ARRAY['L''océan Atlantique', 'La Manche', 'La mer du Nord'], 'fr', true, 'La mer Méditerranée borde les côtes du sud de la France, de Nice à Perpignan.'),
('nature', 1, 'Comment appelle-t-on les animaux qui dorment tout l''hiver ?', 'Des animaux qui hibernent', ARRAY['Des animaux nocturnes', 'Des animaux migrateurs', 'Des animaux diurnes'], 'fr', true, 'L''hibernation est un état de repos prolongé que certains animaux adoptent en hiver.'),
('nature', 1, 'Quel est le plus grand désert chaud du monde ?', 'Le Sahara', ARRAY['Le désert de Gobi', 'Le désert d''Arabie', 'Le désert du Kalahari'], 'fr', true, 'Le Sahara couvre environ 9 millions de km² en Afrique du Nord.'),
('nature', 1, 'Comment appelle-t-on la pluie gelée qui tombe en grains de glace ?', 'La grêle', ARRAY['La neige', 'Le verglas', 'Le givre'], 'fr', true, 'La grêle se forme quand des gouttes d''eau gèlent dans les nuages d''orage.'),
('nature', 1, 'Quel est le plus grand mammifère terrestre ?', 'L''éléphant', ARRAY['La girafe', 'Le rhinocéros', 'L''hippopotame'], 'fr', true, 'L''éléphant d''Afrique est le plus grand animal terrestre, pesant jusqu''à 6 tonnes.'),
('nature', 1, 'De quelle couleur est la lave en fusion ?', 'Rouge-orangé', ARRAY['Bleue', 'Verte', 'Noire'], 'fr', true, 'La lave en fusion est rouge-orangé à cause de sa très haute température.'),
('nature', 1, 'Quel arbre produit des glands ?', 'Le chêne', ARRAY['Le sapin', 'Le bouleau', 'Le hêtre'], 'fr', true, 'Le chêne produit des glands qui servent de nourriture à de nombreux animaux.'),
('nature', 1, 'Qu''est-ce qui fait briller les étoiles ?', 'Des réactions nucléaires', ARRAY['De l''électricité', 'La lumière de la Lune', 'Le frottement de l''air'], 'fr', true, 'Les étoiles brillent grâce à la fusion nucléaire de l''hydrogène en hélium.'),
('nature', 1, 'Comment appelle-t-on un terrain plat et herbeux sans arbres ?', 'Une prairie', ARRAY['Une forêt', 'Un marais', 'Une jungle'], 'fr', true, 'Les prairies sont des écosystèmes dominés par les herbes, avec peu ou pas d''arbres.'),
('nature', 1, 'Quel phénomène naturel fait trembler le sol ?', 'Un tremblement de terre', ARRAY['Une éruption volcanique', 'Un tsunami', 'Un glissement de terrain'], 'fr', true, 'Les tremblements de terre sont causés par le mouvement des plaques tectoniques.'),
('nature', 1, 'Où vivent les poissons ?', 'Dans l''eau', ARRAY['Sur la terre', 'Dans les arbres', 'Dans le sable'], 'fr', true, 'Les poissons respirent dans l''eau grâce à leurs branchies.'),
('nature', 1, 'Comment appelle-t-on un grand bloc de glace flottant dans la mer ?', 'Un iceberg', ARRAY['Un glacier', 'Une banquise', 'Un pack'], 'fr', true, 'Un iceberg est un morceau de glace détaché d''un glacier qui flotte dans l''océan.'),
('nature', 1, 'Quelle planète surnomme-t-on la "planète bleue" ?', 'La Terre', ARRAY['Neptune', 'Uranus', 'Mars'], 'fr', true, 'La Terre est surnommée planète bleue car sa surface est recouverte à 71% d''eau.'),
('nature', 1, 'Quel insecte fabrique de la soie ?', 'Le ver à soie', ARRAY['L''araignée', 'La chenille', 'Le papillon'], 'fr', true, 'Le ver à soie (Bombyx mori) produit un fil de soie pour former son cocon.'),
('nature', 1, 'Que trouve-t-on au centre de la Terre ?', 'Un noyau très chaud', ARRAY['De l''eau', 'Du vide', 'De la glace'], 'fr', true, 'Le noyau terrestre est constitué principalement de fer et de nickel à très haute température.'),
('nature', 1, 'Quelle chaîne de montagnes sépare la France de l''Espagne ?', 'Les Pyrénées', ARRAY['Les Alpes', 'Le Jura', 'Les Vosges'], 'fr', true, 'Les Pyrénées s''étendent sur environ 430 km entre la France et l''Espagne.'),
('nature', 1, 'De quoi est principalement composé le sable des plages ?', 'De minuscules grains de roche', ARRAY['De sel', 'De coquillages uniquement', 'De corail uniquement'], 'fr', true, 'Le sable est principalement constitué de grains de quartz issus de l''érosion des roches.'),
('nature', 1, 'Comment les oiseaux se déplacent-ils sur de longues distances à l''automne ?', 'Ils migrent', ARRAY['Ils hibernent', 'Ils se cachent', 'Ils nagent'], 'fr', true, 'La migration est un déplacement saisonnier que font certains oiseaux vers des régions plus chaudes.'),
('nature', 1, 'Quel est le gaz le plus présent dans l''air que nous respirons ?', 'L''azote', ARRAY['L''oxygène', 'Le dioxyde de carbone', 'L''hydrogène'], 'fr', true, 'L''atmosphère est composée à environ 78% d''azote et 21% d''oxygène.'),
('nature', 1, 'Comment appelle-t-on une étendue d''eau salée entourée de terre ?', 'Une mer intérieure', ARRAY['Un lac', 'Une rivière', 'Un étang'], 'fr', true, 'Une mer intérieure, comme la mer Caspienne, est une grande étendue d''eau salée enclavée.'),
('nature', 1, 'Quelle matière première provient des arbres ?', 'Le bois', ARRAY['Le métal', 'Le plastique', 'Le verre'], 'fr', true, 'Le bois est une ressource naturelle renouvelable produite par les arbres.'),
('nature', 1, 'Quel phénomène forme les stalactites dans les grottes ?', 'L''eau qui s''écoule goutte à goutte', ARRAY['Le vent souterrain', 'La chaleur volcanique', 'Les tremblements de terre'], 'fr', true, 'Les stalactites se forment par le dépôt de calcaire dissous dans l''eau qui s''infiltre.'),
('nature', 1, 'Comment appelle-t-on le cycle de l''eau dans la nature ?', 'Le cycle de l''eau', ARRAY['Le cycle du carbone', 'Le cycle des saisons', 'Le cycle lunaire'], 'fr', true, 'Le cycle de l''eau comprend l''évaporation, la condensation, les précipitations et le ruissellement.'),
('nature', 1, 'Quel est le continent le plus froid ?', 'L''Antarctique', ARRAY['L''Arctique', 'L''Europe', 'L''Asie'], 'fr', true, 'L''Antarctique est le continent le plus froid avec des températures pouvant descendre sous -80°C.'),
('nature', 1, 'Quelle fleur est le symbole du Japon ?', 'Le cerisier en fleurs', ARRAY['La rose', 'La tulipe', 'Le tournesol'], 'fr', true, 'Le cerisier en fleurs (sakura) est un symbole emblématique de la culture japonaise.'),
('nature', 1, 'Comment appelle-t-on un nuage très bas qui réduit la visibilité ?', 'Le brouillard', ARRAY['La brume sèche', 'La rosée', 'Le givre'], 'fr', true, 'Le brouillard est un nuage au niveau du sol qui réduit la visibilité à moins d''un kilomètre.');
INSERT INTO questions (category, difficulty, question_text, correct_answer, wrong_answers, language, is_active, explanation) VALUES
('nature', 2, 'Quel est l''arbre le plus haut du monde ?', 'Le séquoia', ARRAY['Le baobab', 'L''eucalyptus', 'Le sapin de Douglas'], 'fr', true, 'Le séquoia à feuilles d''if (Hyperion) est l''arbre le plus haut connu, mesurant plus de 115 mètres.'),
('nature', 2, 'Quel phénomène lumineux peut-on observer dans le ciel des régions polaires ?', 'Les aurores boréales', ARRAY['Les arcs-en-ciel', 'Les halos solaires', 'Les étoiles filantes'], 'fr', true, 'Les aurores boréales sont causées par l''interaction des particules solaires avec l''atmosphère terrestre.'),
('nature', 2, 'Quelle est la différence entre un fleuve et une rivière ?', 'Le fleuve se jette dans la mer', ARRAY['Le fleuve est plus court', 'La rivière est plus large', 'Le fleuve est souterrain'], 'fr', true, 'Un fleuve se jette directement dans la mer ou l''océan, contrairement à une rivière qui se jette dans un autre cours d''eau.'),
('nature', 2, 'Quel type de roche est formé par le refroidissement de la lave ?', 'Roche volcanique', ARRAY['Roche sédimentaire', 'Roche métamorphique', 'Roche calcaire'], 'fr', true, 'Les roches volcaniques (ou ignées) se forment quand la lave ou le magma refroidit et se solidifie.'),
('nature', 2, 'Comment appelle-t-on la zone de végétation très froide au nord du globe ?', 'La toundra', ARRAY['La taïga', 'La steppe', 'La savane'], 'fr', true, 'La toundra est un biome caractérisé par un sol gelé en permanence (pergélisol) et une végétation rase.'),
('nature', 2, 'Quel est le plus long fleuve du monde ?', 'Le Nil', ARRAY['L''Amazone', 'Le Mississippi', 'Le Yangtsé'], 'fr', true, 'Le Nil mesure environ 6 650 km, traversant l''Afrique du sud au nord.'),
('nature', 2, 'Comment appelle-t-on la transformation d''une chenille en papillon ?', 'La métamorphose', ARRAY['La mutation', 'La mue', 'L''évolution'], 'fr', true, 'La métamorphose est le processus par lequel la chenille se transforme en chrysalide puis en papillon.'),
('nature', 2, 'Quel est le plus grand récif corallien du monde ?', 'La Grande Barrière de corail', ARRAY['Le récif de Belize', 'Le récif de Nouvelle-Calédonie', 'Le récif de la mer Rouge'], 'fr', true, 'La Grande Barrière de corail en Australie s''étend sur plus de 2 300 km.'),
('nature', 2, 'Quelle couche de l''atmosphère protège la Terre des rayons UV ?', 'La couche d''ozone', ARRAY['La troposphère', 'La mésosphère', 'La thermosphère'], 'fr', true, 'La couche d''ozone, située dans la stratosphère, filtre les rayons ultraviolets nocifs du soleil.'),
('nature', 2, 'Comment s''appelle le vent violent qui tourne en spirale ?', 'Une tornade', ARRAY['Un ouragan', 'Un typhon', 'Une mousson'], 'fr', true, 'Une tornade est un tourbillon de vent très violent en forme d''entonnoir reliant un nuage au sol.'),
('nature', 2, 'Quel type de forêt domine en Scandinavie ?', 'La taïga', ARRAY['La forêt tropicale', 'La forêt méditerranéenne', 'La mangrove'], 'fr', true, 'La taïga est une forêt boréale de conifères qui couvre de vastes zones de Scandinavie et de Sibérie.'),
('nature', 2, 'Comment appelle-t-on le sol gelé en permanence des régions arctiques ?', 'Le pergélisol', ARRAY['Le permafrost uniquement', 'Le glacier', 'La banquise'], 'fr', true, 'Le pergélisol est un sol qui reste gelé pendant au moins deux années consécutives.'),
('nature', 2, 'Quel minéral est le plus dur selon l''échelle de Mohs ?', 'Le diamant', ARRAY['Le rubis', 'Le quartz', 'Le saphir'], 'fr', true, 'Le diamant a une dureté de 10 sur l''échelle de Mohs, c''est le minéral naturel le plus dur.'),
('nature', 2, 'Quelle est la principale cause de l''érosion des côtes ?', 'Les vagues', ARRAY['Le vent', 'La pluie', 'Les tremblements de terre'], 'fr', true, 'Les vagues sont le principal agent d''érosion côtière, sculptant les falaises et les plages.'),
('nature', 2, 'Comment appelle-t-on un écosystème d''eau stagnante ?', 'Un étang ou un lac', ARRAY['Une rivière', 'Un torrent', 'Un ruisseau'], 'fr', true, 'Les écosystèmes lentiques comprennent les lacs, étangs et mares, où l''eau est relativement stagnante.'),
('nature', 2, 'Quel parc naturel français est connu pour ses chevaux sauvages ?', 'La Camargue', ARRAY['Le Mercantour', 'Les Cévennes', 'Le Vercors'], 'fr', true, 'La Camargue est célèbre pour ses chevaux blancs, ses taureaux et ses flamants roses.'),
('nature', 2, 'Quelle est la principale source d''énergie renouvelable en France ?', 'L''énergie hydraulique', ARRAY['L''énergie solaire', 'L''énergie éolienne', 'La biomasse'], 'fr', true, 'L''hydroélectricité est historiquement la première source d''énergie renouvelable en France.'),
('nature', 2, 'Comment s''appelle le processus par lequel l''eau s''évapore des feuilles ?', 'L''évapotranspiration', ARRAY['La photosynthèse', 'La respiration', 'L''osmose'], 'fr', true, 'L''évapotranspiration est le processus par lequel l''eau passe des plantes à l''atmosphère via les feuilles.'),
('nature', 2, 'Quel est le plus grand lac d''eau douce d''Europe ?', 'Le lac Ladoga', ARRAY['Le lac Léman', 'Le lac de Constance', 'Le lac Balaton'], 'fr', true, 'Le lac Ladoga en Russie couvre environ 17 700 km², c''est le plus grand lac d''Europe.'),
('nature', 2, 'Quelle catastrophe naturelle est provoquée par un séisme sous-marin ?', 'Un tsunami', ARRAY['Un ouragan', 'Un cyclone', 'Une inondation fluviale'], 'fr', true, 'Un tsunami est une série de vagues géantes causées par un déplacement brutal du fond marin.'),
('nature', 2, 'Comment appelle-t-on les roches formées par accumulation de sédiments ?', 'Les roches sédimentaires', ARRAY['Les roches volcaniques', 'Les roches métamorphiques', 'Les roches cristallines'], 'fr', true, 'Les roches sédimentaires se forment par l''accumulation et la compaction de sédiments au fil du temps.'),
('nature', 2, 'Quel est le plus grand parc national de France métropolitaine ?', 'Le Parc national des Écrins', ARRAY['Le Parc national des Cévennes', 'Le Parc national du Mercantour', 'Le Parc national de la Vanoise'], 'fr', true, 'Le Parc national des Écrins couvre environ 918 km² de zone cœur dans les Alpes.'),
('nature', 2, 'Quelle roche est utilisée pour fabriquer du ciment ?', 'Le calcaire', ARRAY['Le granit', 'Le basalte', 'Le marbre'], 'fr', true, 'Le calcaire est la matière première principale pour la fabrication du ciment.'),
('nature', 2, 'Quel animal est le principal pollinisateur des fleurs ?', 'L''abeille', ARRAY['Le papillon', 'Le colibri', 'La mouche'], 'fr', true, 'Les abeilles sont responsables de la pollinisation d''environ 80% des plantes à fleurs.'),
('nature', 2, 'Comment appelle-t-on une zone humide avec des arbres adaptés à l''eau salée ?', 'Une mangrove', ARRAY['Un marais', 'Une tourbière', 'Un marécage'], 'fr', true, 'Les mangroves sont des forêts côtières tropicales dont les arbres ont des racines adaptées à l''eau salée.'),
('nature', 2, 'Quel volcan italien est célèbre pour avoir détruit Pompéi ?', 'Le Vésuve', ARRAY['L''Etna', 'Le Stromboli', 'Le Vulcano'], 'fr', true, 'Le Vésuve a détruit Pompéi et Herculanum lors de son éruption en 79 après J.-C.'),
('nature', 2, 'Comment appelle-t-on la zone où l''eau de mer rencontre l''eau douce ?', 'Un estuaire', ARRAY['Un delta', 'Un fjord', 'Une baie'], 'fr', true, 'Un estuaire est une zone de transition entre l''eau douce d''un fleuve et l''eau salée de la mer.'),
('nature', 2, 'Quelle énergie utilise la chaleur interne de la Terre ?', 'L''énergie géothermique', ARRAY['L''énergie solaire', 'L''énergie éolienne', 'L''énergie marémotrice'], 'fr', true, 'L''énergie géothermique exploite la chaleur naturelle provenant de l''intérieur de la Terre.'),
('nature', 2, 'Quel est le plus haut sommet du monde ?', 'L''Everest', ARRAY['Le K2', 'Le Kangchenjunga', 'Le Makalu'], 'fr', true, 'L''Everest culmine à 8 849 mètres dans la chaîne de l''Himalaya.'),
('nature', 2, 'Comment appelle-t-on un terrain marécageux riche en tourbe ?', 'Une tourbière', ARRAY['Une prairie', 'Une lande', 'Un bocage'], 'fr', true, 'Les tourbières sont des zones humides où la matière végétale se décompose très lentement et forme de la tourbe.'),
('nature', 2, 'Quel gaz à effet de serre est le plus émis par les activités humaines ?', 'Le dioxyde de carbone (CO2)', ARRAY['Le méthane', 'Le protoxyde d''azote', 'L''ozone'], 'fr', true, 'Le CO2 représente environ 75% des émissions de gaz à effet de serre d''origine humaine.'),
('nature', 2, 'Quel est le biome le plus riche en biodiversité ?', 'La forêt tropicale', ARRAY['La savane', 'La forêt tempérée', 'Le récif corallien'], 'fr', true, 'Les forêts tropicales abritent plus de 50% des espèces animales et végétales terrestres.'),
('nature', 2, 'Comment s''appelle le phénomène de montée des eaux d''un cours d''eau ?', 'Une crue', ARRAY['Une marée', 'Un raz-de-marée', 'Une sécheresse'], 'fr', true, 'Une crue est une augmentation temporaire du débit et du niveau d''un cours d''eau.'),
('nature', 2, 'Quelle montagne française est un ancien volcan ?', 'Le Puy de Dôme', ARRAY['Le Mont Blanc', 'La Meije', 'Le Pic du Midi'], 'fr', true, 'Le Puy de Dôme est un ancien volcan de la chaîne des Puys en Auvergne, éteint depuis 12 000 ans.'),
('nature', 2, 'Quel est le rôle principal des forêts dans le cycle du carbone ?', 'Absorber le CO2', ARRAY['Produire du CO2', 'Stocker de l''azote', 'Évaporer l''eau'], 'fr', true, 'Les forêts sont des puits de carbone : elles absorbent le CO2 par la photosynthèse et le stockent dans le bois.'),
('nature', 2, 'Comment appelle-t-on les vagues géantes causées par le vent en haute mer ?', 'La houle', ARRAY['Le ressac', 'Le mascaret', 'Le courant'], 'fr', true, 'La houle est une ondulation régulière de la surface de la mer, générée par le vent au large.'),
('nature', 2, 'Quel type de climat caractérise le sud de la France ?', 'Climat méditerranéen', ARRAY['Climat continental', 'Climat océanique', 'Climat tropical'], 'fr', true, 'Le climat méditerranéen se caractérise par des étés chauds et secs et des hivers doux et humides.'),
('nature', 2, 'Comment s''appelle le phénomène de disparition des espèces animales ?', 'L''extinction', ARRAY['La migration', 'L''adaptation', 'L''évolution'], 'fr', true, 'L''extinction est la disparition complète d''une espèce, un processus souvent accéléré par les activités humaines.'),
('nature', 2, 'Quelle vallée française est célèbre pour ses châteaux et ses vignobles ?', 'La vallée de la Loire', ARRAY['La vallée du Rhône', 'La vallée de la Dordogne', 'La vallée de la Moselle'], 'fr', true, 'La vallée de la Loire est inscrite au patrimoine mondial de l''UNESCO pour ses paysages et châteaux.'),
('nature', 2, 'Quel est le principal gaz responsable de l''effet de serre naturel ?', 'La vapeur d''eau', ARRAY['Le CO2', 'Le méthane', 'L''ozone'], 'fr', true, 'La vapeur d''eau est le gaz à effet de serre le plus abondant dans l''atmosphère terrestre.'),
('nature', 2, 'Comment appelle-t-on une longue période sans pluie ?', 'Une sécheresse', ARRAY['Une canicule', 'Un anticyclone', 'Une mousson'], 'fr', true, 'La sécheresse est un déficit prolongé de précipitations qui peut affecter les écosystèmes et l''agriculture.'),
('nature', 2, 'Quel continent abrite la plus grande forêt tropicale ?', 'L''Amérique du Sud', ARRAY['L''Afrique', 'L''Asie', 'L''Océanie'], 'fr', true, 'L''Amazonie en Amérique du Sud est la plus grande forêt tropicale du monde.'),
('nature', 2, 'Comment appelle-t-on un sol riche en matière organique décomposée ?', 'L''humus', ARRAY['L''argile', 'Le limon', 'Le sable'], 'fr', true, 'L''humus est la couche supérieure du sol formée par la décomposition de matière organique.'),
('nature', 2, 'Quelle île française d''outre-mer possède un volcan actif, le Piton de la Fournaise ?', 'La Réunion', ARRAY['La Guadeloupe', 'La Martinique', 'Mayotte'], 'fr', true, 'Le Piton de la Fournaise à La Réunion est l''un des volcans les plus actifs au monde.'),
('nature', 2, 'Quel phénomène météo crée un mur d''eau qui remonte un fleuve ?', 'Le mascaret', ARRAY['Le tsunami', 'La crue', 'Le raz-de-marée'], 'fr', true, 'Le mascaret est une vague qui remonte un fleuve lors de grandes marées, observable sur la Gironde.'),
('nature', 2, 'Quelle est la couche la plus externe de la Terre ?', 'La croûte terrestre', ARRAY['Le manteau', 'Le noyau externe', 'Le noyau interne'], 'fr', true, 'La croûte terrestre est la couche superficielle solide de la Terre, épaisse de 5 à 70 km.'),
('nature', 2, 'Quel est le plus grand volcan actif d''Europe ?', 'L''Etna', ARRAY['Le Vésuve', 'Le Stromboli', 'L''Eyjafjallajökull'], 'fr', true, 'L''Etna en Sicile culmine à environ 3 357 mètres et est régulièrement en éruption.'),
('nature', 2, 'Comment appelle-t-on le phénomène de réchauffement excessif de la planète ?', 'Le réchauffement climatique', ARRAY['L''effet de serre naturel', 'L''inversion thermique', 'El Niño'], 'fr', true, 'Le réchauffement climatique est l''augmentation de la température moyenne de la Terre due aux activités humaines.'),
('nature', 2, 'Quel panneau solaire transforme la lumière en électricité ?', 'Un panneau photovoltaïque', ARRAY['Un panneau thermique', 'Un panneau réflecteur', 'Un panneau infrarouge'], 'fr', true, 'Les panneaux photovoltaïques convertissent directement la lumière du soleil en électricité.');
INSERT INTO questions (category, difficulty, question_text, correct_answer, wrong_answers, language, is_active, explanation) VALUES
('nature', 3, 'Quel est le pH de l''eau pure ?', '7', ARRAY['5', '9', '0'], 'fr', true, 'L''eau pure a un pH neutre de 7, ni acide ni basique.'),
('nature', 3, 'Comment appelle-t-on le processus de dégradation des roches par les intempéries ?', 'L''érosion', ARRAY['La sédimentation', 'La cristallisation', 'La fossilisation'], 'fr', true, 'L''érosion est le processus par lequel les roches sont usées et transportées par l''eau, le vent ou la glace.'),
('nature', 3, 'Quelle est la principale différence entre le granit et le basalte ?', 'Leur vitesse de refroidissement', ARRAY['Leur couleur uniquement', 'Leur âge', 'Leur localisation'], 'fr', true, 'Le granit refroidit lentement en profondeur (gros cristaux) tandis que le basalte refroidit vite en surface (cristaux fins).'),
('nature', 3, 'Comment s''appelle le courant marin chaud qui traverse l''Atlantique Nord ?', 'Le Gulf Stream', ARRAY['El Niño', 'Le Kuroshio', 'Le courant de Humboldt'], 'fr', true, 'Le Gulf Stream est un courant marin chaud qui influence le climat de l''Europe occidentale.'),
('nature', 3, 'Quel est le nom du supercontinent qui existait il y a 250 millions d''années ?', 'La Pangée', ARRAY['La Laurasie', 'Le Gondwana', 'La Rodinia'], 'fr', true, 'La Pangée était un supercontinent qui regroupait toutes les terres émergées avant de se fragmenter.'),
('nature', 3, 'Quelle est la profondeur maximale approximative de la fosse des Mariannes ?', '11 000 mètres', ARRAY['8 000 mètres', '15 000 mètres', '6 000 mètres'], 'fr', true, 'La fosse des Mariannes dans l''océan Pacifique atteint environ 11 034 mètres de profondeur.'),
('nature', 3, 'Comment s''appelle la symbiose entre un champignon et les racines d''un arbre ?', 'La mycorhize', ARRAY['Le parasitisme', 'Le commensalisme', 'Le lichen'], 'fr', true, 'La mycorhize est une association mutuellement bénéfique entre champignon et racines végétales.'),
('nature', 3, 'Quel phénomène climatique cyclique réchauffe les eaux du Pacifique tropical ?', 'El Niño', ARRAY['La Niña', 'Le Gulf Stream', 'L''ENSO'], 'fr', true, 'El Niño est un réchauffement anormal des eaux du Pacifique oriental qui perturbe le climat mondial.'),
('nature', 3, 'Quelle échelle mesure l''intensité des ouragans ?', 'L''échelle de Saffir-Simpson', ARRAY['L''échelle de Richter', 'L''échelle de Beaufort', 'L''échelle de Mercalli'], 'fr', true, 'L''échelle de Saffir-Simpson classe les ouragans de catégorie 1 à 5 selon la vitesse des vents.'),
('nature', 3, 'Comment appelle-t-on la ligne de partage des eaux entre deux bassins versants ?', 'La ligne de crête', ARRAY['Le talweg', 'L''isthme', 'Le confluent'], 'fr', true, 'La ligne de partage des eaux sépare les bassins versants de différents cours d''eau.'),
('nature', 3, 'Quel type de volcan a une forme conique avec des couches alternées de lave et de cendres ?', 'Un stratovolcan', ARRAY['Un volcan bouclier', 'Un cône de scories', 'Un maar'], 'fr', true, 'Les stratovolcans, comme le Vésuve ou le Fuji, sont formés par l''alternance de coulées de lave et de dépôts pyroclastiques.'),
('nature', 3, 'Quel est le nom du phénomène où les océans absorbent le CO2 et deviennent plus acides ?', 'L''acidification des océans', ARRAY['L''eutrophisation', 'La salinisation', 'La désoxygénation'], 'fr', true, 'L''acidification des océans est causée par l''absorption du CO2 atmosphérique, menaçant les organismes calcaires.'),
('nature', 3, 'Comment s''appelle le processus de formation d''un sol à partir de la roche mère ?', 'La pédogenèse', ARRAY['La lithogenèse', 'La diagenèse', 'L''orogenèse'], 'fr', true, 'La pédogenèse est l''ensemble des processus physiques, chimiques et biologiques qui transforment la roche en sol.'),
('nature', 3, 'Quelle est la cause principale de la déforestation en Amazonie ?', 'L''élevage bovin', ARRAY['L''exploitation minière', 'La construction de routes', 'Le tourisme'], 'fr', true, 'L''élevage bovin est la première cause de déforestation en Amazonie, représentant environ 80% des zones déboisées.'),
('nature', 3, 'Comment appelle-t-on la zone de transition entre deux écosystèmes ?', 'L''écotone', ARRAY['Le biotope', 'La biocénose', 'L''écozone'], 'fr', true, 'L''écotone est une zone de transition écologique entre deux biomes ou écosystèmes adjacents.'),
('nature', 3, 'Quel type de nuage est associé aux orages violents ?', 'Le cumulonimbus', ARRAY['Le cirrus', 'Le stratus', 'L''altocumulus'], 'fr', true, 'Le cumulonimbus est un nuage à développement vertical pouvant atteindre 15 km, produisant orages et grêle.'),
('nature', 3, 'Quelle roche métamorphique provient de la transformation du calcaire ?', 'Le marbre', ARRAY['L''ardoise', 'Le gneiss', 'Le schiste'], 'fr', true, 'Le marbre est formé par la recristallisation du calcaire sous l''effet de la chaleur et de la pression.'),
('nature', 3, 'Quel est le principal mécanisme de dispersion des graines chez les pissenlits ?', 'Le vent (anémochorie)', ARRAY['L''eau (hydrochorie)', 'Les animaux (zoochorie)', 'La gravité (barochorie)'], 'fr', true, 'Les graines de pissenlit possèdent des aigrettes qui leur permettent d''être transportées par le vent.'),
('nature', 3, 'Comment s''appelle la remontée d''eau froide profonde vers la surface de l''océan ?', 'L''upwelling', ARRAY['Le downwelling', 'La thermocline', 'Le courant de fond'], 'fr', true, 'L''upwelling ramène des eaux froides riches en nutriments vers la surface, favorisant la vie marine.'),
('nature', 3, 'Quel est le nom de la couche de sol située juste sous l''humus ?', 'L''horizon B (sous-sol)', ARRAY['L''horizon C (roche altérée)', 'L''horizon R (roche mère)', 'L''horizon E (éluvial)'], 'fr', true, 'L''horizon B, ou sous-sol, est la couche d''accumulation des minéraux lessivés depuis les couches supérieures.'),
('nature', 3, 'Quelle particularité géologique fait de l''Islande un lieu unique ?', 'Elle est située sur une dorsale médio-océanique', ARRAY['Elle est sur une plaque unique', 'Elle n''a aucun volcan', 'Elle est entièrement granitique'], 'fr', true, 'L''Islande est l''un des rares endroits où la dorsale médio-atlantique émerge au-dessus de la surface de l''eau.'),
('nature', 3, 'Comment appelle-t-on la capacité d''un écosystème à retrouver son état initial après une perturbation ?', 'La résilience', ARRAY['La résistance', 'La succession', 'La régénération'], 'fr', true, 'La résilience écologique est la capacité d''un écosystème à se rétablir après un stress ou une perturbation.'),
('nature', 3, 'Quelle est la principale source naturelle d''émission de méthane ?', 'Les zones humides', ARRAY['Les volcans', 'Les océans', 'Les forêts'], 'fr', true, 'Les zones humides sont la plus grande source naturelle de méthane due à la décomposition anaérobie de matière organique.'),
('nature', 3, 'Quel processus géologique crée les chaînes de montagnes ?', 'L''orogenèse', ARRAY['L''érosion', 'La subduction seule', 'Le volcanisme'], 'fr', true, 'L''orogenèse est le processus de formation des montagnes par collision de plaques tectoniques.'),
('nature', 3, 'Comment s''appelle l''ensemble des êtres vivants microscopiques flottant dans l''eau ?', 'Le plancton', ARRAY['Le necton', 'Le benthos', 'Le neuston'], 'fr', true, 'Le plancton regroupe les organismes microscopiques (phyto et zooplancton) qui dérivent dans l''eau.'),
('nature', 3, 'Quel phénomène provoque l''inversion des pôles magnétiques terrestres ?', 'Les mouvements du noyau externe liquide', ARRAY['Les tempêtes solaires', 'La rotation de la Terre', 'Les marées'], 'fr', true, 'Les inversions magnétiques sont causées par les mouvements de convection du fer liquide dans le noyau externe.'),
('nature', 3, 'Quelle est la vitesse approximative de déplacement des plaques tectoniques ?', 'Quelques centimètres par an', ARRAY['Quelques mètres par an', 'Quelques millimètres par siècle', 'Quelques kilomètres par an'], 'fr', true, 'Les plaques tectoniques se déplacent en moyenne de 2 à 10 centimètres par an.'),
('nature', 3, 'Comment appelle-t-on un lac formé dans le cratère d''un volcan ?', 'Un lac de cratère', ARRAY['Un lac glaciaire', 'Un lac tectonique', 'Un lac de barrage'], 'fr', true, 'Un lac de cratère se forme lorsque l''eau s''accumule dans la dépression laissée par un cratère volcanique.'),
('nature', 3, 'Quel est le rôle des récifs coralliens pour les écosystèmes marins ?', 'Ils fournissent habitat et protection à 25% des espèces marines', ARRAY['Ils produisent de l''oxygène uniquement', 'Ils filtrent le sel de l''eau', 'Ils régulent la température océanique'], 'fr', true, 'Les récifs coralliens abritent environ un quart de toutes les espèces marines connues.'),
('nature', 3, 'Quel métal est extrait de la bauxite ?', 'L''aluminium', ARRAY['Le cuivre', 'Le fer', 'Le zinc'], 'fr', true, 'La bauxite est le principal minerai utilisé pour produire de l''aluminium par un procédé électrolytique.'),
('nature', 3, 'Comment s''appelle le phénomène de dépôt de sel quand l''eau de mer s''évapore ?', 'L''évaporite', ARRAY['La cristallisation ignée', 'La précipitation chimique', 'La sublimation'], 'fr', true, 'Les évaporites sont des roches sédimentaires formées par l''évaporation de l''eau et le dépôt de sels dissous.'),
('nature', 3, 'Quelle est la différence principale entre une stalactite et une stalagmite ?', 'La stalactite descend du plafond, la stalagmite monte du sol', ARRAY['La stalactite est plus grande', 'La stalagmite est en calcaire uniquement', 'La stalactite est creuse'], 'fr', true, 'Les stalactites pendent du plafond (elles « tiennent ») et les stalagmites s''élèvent du sol (elles « montent »).'),
('nature', 3, 'Quel est le pourcentage approximatif d''eau douce disponible sur Terre ?', 'Environ 3%', ARRAY['Environ 10%', 'Environ 25%', 'Environ 50%'], 'fr', true, 'Seulement environ 3% de l''eau sur Terre est de l''eau douce, et une grande partie est piégée dans les glaciers.'),
('nature', 3, 'Comment appelle-t-on l''ensemble des espèces végétales d''une région ?', 'La flore', ARRAY['La faune', 'La biocénose', 'Le biote'], 'fr', true, 'La flore désigne l''ensemble des espèces de plantes présentes dans une zone géographique donnée.'),
('nature', 3, 'Quel type d''éruption volcanique est le plus explosif ?', 'L''éruption plinienne', ARRAY['L''éruption hawaïenne', 'L''éruption strombolienne', 'L''éruption effusive'], 'fr', true, 'L''éruption plinienne est caractérisée par des explosions violentes et des colonnes de cendres pouvant atteindre 45 km.'),
('nature', 3, 'Quelle est la fonction principale des zones humides pour l''environnement ?', 'Filtrer et purifier l''eau', ARRAY['Produire de l''oxygène', 'Réguler les marées', 'Stocker le méthane'], 'fr', true, 'Les zones humides agissent comme des filtres naturels et des éponges qui régulent les inondations.'),
('nature', 3, 'Comment appelle-t-on la succession écologique qui se produit après un incendie de forêt ?', 'La succession secondaire', ARRAY['La succession primaire', 'La climax', 'La régression'], 'fr', true, 'La succession secondaire se produit sur un substrat déjà colonisé mais perturbé, comme après un feu.'),
('nature', 3, 'Quel est le nom de la faille géologique majeure en Californie ?', 'La faille de San Andreas', ARRAY['La faille du Rift', 'La faille de Hayward', 'La faille du Pacifique'], 'fr', true, 'La faille de San Andreas est une faille transformante de 1 300 km entre les plaques pacifique et nord-américaine.'),
('nature', 3, 'Quelle est l''altitude moyenne à laquelle se forment les nuages de type cirrus ?', 'Au-dessus de 6 000 mètres', ARRAY['En dessous de 2 000 mètres', 'Entre 2 000 et 4 000 mètres', 'Au niveau de la mer'], 'fr', true, 'Les cirrus sont des nuages de haute altitude composés de cristaux de glace.'),
('nature', 3, 'Comment appelle-t-on le phénomène de blanchissement des coraux ?', 'Le blanchissement corallien', ARRAY['L''érosion corallienne', 'La calcification corallienne', 'La fossilisation corallienne'], 'fr', true, 'Le blanchissement est causé par l''expulsion des algues symbiotiques due au stress thermique.'),
('nature', 3, 'Quel est le plus grand delta fluvial du monde ?', 'Le delta du Gange-Brahmapoutre', ARRAY['Le delta du Nil', 'Le delta du Mississippi', 'Le delta du Mékong'], 'fr', true, 'Le delta du Gange-Brahmapoutre au Bangladesh couvre environ 105 000 km².'),
('nature', 3, 'Quelle propriété de l''eau la rend unique parmi les liquides courants ?', 'Elle est plus dense à l''état liquide qu''à l''état solide', ARRAY['Elle bout à 100°C', 'Elle est transparente', 'Elle conduit l''électricité'], 'fr', true, 'La glace flotte car l''eau est plus dense à 4°C qu''à 0°C, une propriété essentielle pour la vie aquatique.'),
('nature', 3, 'Comment s''appelle le processus de transformation des roches sous l''effet de la pression et de la chaleur ?', 'Le métamorphisme', ARRAY['La diagenèse', 'L''altération', 'La fusion'], 'fr', true, 'Le métamorphisme transforme les roches existantes sans les fondre, créant des roches métamorphiques.'),
('nature', 3, 'Quel gaz est libéré par la décomposition de matière organique dans les marais ?', 'Le méthane', ARRAY['L''oxygène', 'L''azote', 'L''hélium'], 'fr', true, 'Le méthane (CH4) est produit par les bactéries méthanogènes lors de la décomposition anaérobie.'),
('nature', 3, 'Comment appelle-t-on l''écosystème de la zone intertidale, entre marée haute et marée basse ?', 'L''estran', ARRAY['Le platier', 'Le littoral', 'La vasière'], 'fr', true, 'L''estran est la zone du rivage alternativement couverte et découverte par la marée.'),
('nature', 3, 'Quel phénomène atmosphérique crée les vents ?', 'Les différences de pression atmosphérique', ARRAY['La rotation de la Terre uniquement', 'L''attraction lunaire', 'Les courants océaniques'], 'fr', true, 'Le vent est créé par le déplacement d''air des zones de haute pression vers les zones de basse pression.'),
('nature', 3, 'Quelle est la particularité du lac Baïkal en Russie ?', 'C''est le lac le plus profond du monde', ARRAY['C''est le lac le plus grand du monde', 'C''est le lac le plus salé du monde', 'C''est le lac le plus chaud du monde'], 'fr', true, 'Le lac Baïkal atteint 1 642 mètres de profondeur et contient environ 20% des eaux douces non gelées.'),
('nature', 3, 'Comment s''appelle la couche de la Terre située entre la croûte et le noyau ?', 'Le manteau', ARRAY['L''asthénosphère uniquement', 'La lithosphère', 'La mésosphère'], 'fr', true, 'Le manteau terrestre représente environ 84% du volume de la Terre, entre la croûte et le noyau.'),
('nature', 3, 'Quel est le principal facteur qui détermine le climat d''une région ?', 'La latitude', ARRAY['La longitude', 'L''altitude uniquement', 'La végétation'], 'fr', true, 'La latitude est le principal facteur climatique car elle détermine l''angle d''incidence des rayons solaires.'),
('nature', 3, 'Comment appelle-t-on le cycle biogéochimique de l''azote ?', 'Le cycle de l''azote', ARRAY['Le cycle du phosphore', 'Le cycle du soufre', 'Le cycle du carbone'], 'fr', true, 'Le cycle de l''azote inclut la fixation, la nitrification, la dénitrification et l''ammonification.');
INSERT INTO questions (category, difficulty, question_text, correct_answer, wrong_answers, language, is_active, explanation) VALUES
('nature', 4, 'Quel est le gaz le plus abondant dans l''atmosphère terrestre ?', 'L''azote (78%)', ARRAY['L''oxygène (78%)', 'Le dioxyde de carbone (78%)', 'L''argon (78%)'], 'fr', true, 'L''azote compose environ 78% de l''atmosphère, suivi de l''oxygène à 21%.'),
('nature', 4, 'Comment s''appelle le processus par lequel une roche sédimentaire se transforme en roche métamorphique ?', 'Le métamorphisme régional', ARRAY['La diagenèse', 'La lithification', 'L''anatexie'], 'fr', true, 'Le métamorphisme régional transforme les roches sur de grandes surfaces sous l''effet de la pression et de la chaleur.'),
('nature', 4, 'Quel est le nom du phénomène de circulation thermohaline des océans ?', 'Le tapis roulant océanique', ARRAY['Le courant jet', 'La circulation de Hadley', 'Le cycle de Walker'], 'fr', true, 'La circulation thermohaline est un système de courants océaniques profonds entraîné par les différences de température et de salinité.'),
('nature', 4, 'Quelle est la cause principale des inversions de température dans l''atmosphère ?', 'Le refroidissement radiatif du sol', ARRAY['Le réchauffement solaire direct', 'La rotation de la Terre', 'Les éruptions volcaniques'], 'fr', true, 'L''inversion thermique se produit quand l''air froid reste piégé sous une couche d''air chaud, souvent par refroidissement nocturne du sol.'),
('nature', 4, 'Comment appelle-t-on la zone de subduction où une plaque océanique plonge sous une plaque continentale ?', 'La fosse océanique', ARRAY['La dorsale', 'Le rift', 'Le graben'], 'fr', true, 'Les fosses océaniques se forment aux zones de subduction où la plaque océanique, plus dense, plonge sous la plaque continentale.'),
('nature', 4, 'Quel est le processus de fixation biologique de l''azote atmosphérique ?', 'La fixation par les bactéries rhizobium', ARRAY['L''absorption directe par les feuilles', 'La décomposition des roches', 'La photosynthèse'], 'fr', true, 'Les bactéries Rhizobium dans les nodosités des légumineuses convertissent l''azote atmosphérique en ammonium assimilable.'),
('nature', 4, 'Quelle est la différence entre un fjord et un ria ?', 'Le fjord est creusé par un glacier, la ria par une rivière', ARRAY['Le fjord est tropical, la ria est polaire', 'Le fjord est d''eau douce, la ria d''eau salée', 'Le fjord est plus petit que la ria'], 'fr', true, 'Les fjords sont des vallées glaciaires inondées tandis que les rias sont des vallées fluviales submergées par la montée des eaux.'),
('nature', 4, 'Comment s''appelle le phénomène de fluorescence bleue observée dans certaines baies tropicales ?', 'La bioluminescence', ARRAY['La phosphorescence', 'La réfraction', 'La diffraction'], 'fr', true, 'La bioluminescence marine est produite par des dinoflagellés qui émettent de la lumière lorsqu''ils sont agités.'),
('nature', 4, 'Quel est le nom du processus de datation des roches par la désintégration radioactive ?', 'La datation radiométrique', ARRAY['La datation stratigraphique', 'La dendrochronologie', 'La paléomagnétisme'], 'fr', true, 'La datation radiométrique utilise la demi-vie des isotopes radioactifs pour déterminer l''âge absolu des roches.'),
('nature', 4, 'Quelle est la particularité des sols latéritiques des régions tropicales ?', 'Ils sont riches en oxydes de fer et d''aluminium', ARRAY['Ils sont riches en humus', 'Ils sont très fertiles', 'Ils contiennent beaucoup de calcaire'], 'fr', true, 'Les latérites sont des sols tropicaux rouges appauvris en silice mais enrichis en oxydes de fer et d''aluminium.'),
('nature', 4, 'Comment appelle-t-on la zone d''un aquifère où l''eau est sous pression ?', 'Un aquifère captif', ARRAY['Un aquifère libre', 'Une nappe perchée', 'Un karst'], 'fr', true, 'Un aquifère captif est coincé entre deux couches imperméables, créant une pression qui peut faire jaillir l''eau.'),
('nature', 4, 'Quel phénomène géologique produit les geysers ?', 'Le chauffage de l''eau souterraine par le magma', ARRAY['La pression atmosphérique', 'Les marées souterraines', 'L''activité sismique directe'], 'fr', true, 'Les geysers se forment quand l''eau souterraine est surchauffée par le magma et jaillit périodiquement sous pression.'),
('nature', 4, 'Quelle est la principale conséquence de l''eutrophisation d''un lac ?', 'La prolifération d''algues et la diminution de l''oxygène', ARRAY['L''augmentation de la salinité', 'L''acidification de l''eau', 'La baisse du niveau d''eau'], 'fr', true, 'L''eutrophisation entraîne une croissance excessive d''algues qui, en se décomposant, épuisent l''oxygène dissous.'),
('nature', 4, 'Comment s''appelle le phénomène d''affaissement du sol dû au retrait du pergélisol ?', 'Le thermokarst', ARRAY['Le karstification', 'La subsidence tectonique', 'L''effondrement minier'], 'fr', true, 'Le thermokarst est un paysage formé par la fonte du pergélisol, créant des dépressions et des lacs.'),
('nature', 4, 'Quel est le rôle de l''albédo dans le système climatique ?', 'Il mesure la fraction de lumière solaire réfléchie par une surface', ARRAY['Il mesure la température de surface', 'Il mesure l''humidité atmosphérique', 'Il mesure la vitesse du vent'], 'fr', true, 'L''albédo varie de 0 (absorption totale) à 1 (réflexion totale). La neige a un albédo élevé, l''océan un albédo faible.'),
('nature', 4, 'Quelle est la profondeur moyenne de la zone photique dans l''océan ?', 'Environ 200 mètres', ARRAY['Environ 50 mètres', 'Environ 1 000 mètres', 'Environ 500 mètres'], 'fr', true, 'La zone photique (ou euphotique) est la couche d''eau où la lumière pénètre suffisamment pour permettre la photosynthèse.'),
('nature', 4, 'Comment appelle-t-on le phénomène de migration verticale quotidienne du zooplancton ?', 'La migration nycthémérale', ARRAY['La migration saisonnière', 'La migration trophique', 'La migration latitudinale'], 'fr', true, 'Le zooplancton remonte en surface la nuit pour se nourrir et descend en profondeur le jour pour éviter les prédateurs.'),
('nature', 4, 'Quel est le nom du processus de formation des diamants dans la nature ?', 'La cristallisation du carbone sous haute pression dans le manteau', ARRAY['La fossilisation du charbon', 'La compression du quartz', 'L''érosion volcanique'], 'fr', true, 'Les diamants se forment à plus de 150 km de profondeur sous des pressions et températures extrêmes.'),
('nature', 4, 'Quelle est la relation entre la déforestation et le cycle de l''eau ?', 'La déforestation réduit l''évapotranspiration et les précipitations locales', ARRAY['La déforestation augmente les précipitations', 'Elle n''a aucun effet sur le cycle de l''eau', 'Elle augmente l''humidité du sol'], 'fr', true, 'Sans arbres, l''évapotranspiration diminue, réduisant les précipitations locales et augmentant le ruissellement.'),
('nature', 4, 'Comment appelle-t-on les organismes qui vivent dans les sources hydrothermales au fond des océans ?', 'Les organismes chimiosynthétiques', ARRAY['Les organismes photosynthétiques', 'Les organismes saprophytes', 'Les organismes parasites'], 'fr', true, 'Les organismes chimiosynthétiques utilisent l''énergie chimique des composés sulfurés au lieu de la lumière.'),
('nature', 4, 'Quel est le nom de la plus grande extinction de masse dans l''histoire de la Terre ?', 'L''extinction du Permien-Trias', ARRAY['L''extinction du Crétacé-Tertiaire', 'L''extinction de l''Ordovicien', 'L''extinction du Dévonien'], 'fr', true, 'L''extinction du Permien-Trias il y a 252 millions d''années a éliminé environ 96% des espèces marines.'),
('nature', 4, 'Quelle est la différence entre la météorologie et la climatologie ?', 'La météo étudie le court terme, la climatologie le long terme', ARRAY['Elles étudient la même chose', 'La climatologie étudie les océans', 'La météorologie étudie les volcans'], 'fr', true, 'La météorologie analyse les conditions atmosphériques à court terme, la climatologie les tendances sur des décennies.'),
('nature', 4, 'Comment s''appelle le processus par lequel les plantes perdent leurs feuilles à l''automne ?', 'L''abscission', ARRAY['La défoliation', 'La sénescence', 'La dormance'], 'fr', true, 'L''abscission est le processus actif par lequel les arbres décidus détachent leurs feuilles en formant une couche de séparation.'),
('nature', 4, 'Quel est le lien entre les courants-jets (jet streams) et la météo en Europe ?', 'Ils dirigent les systèmes météorologiques d''ouest en est', ARRAY['Ils n''ont aucun effet sur l''Europe', 'Ils bloquent les précipitations', 'Ils créent les aurores boréales'], 'fr', true, 'Les courants-jets sont des vents d''altitude qui guident les dépressions et anticyclones traversant l''Europe.'),
('nature', 4, 'Quelle est la cause principale de la formation des dunes de sable ?', 'L''interaction entre le vent et les obstacles au sol', ARRAY['Les marées', 'L''érosion fluviale', 'L''activité volcanique'], 'fr', true, 'Les dunes se forment quand le vent transporte du sable et le dépose contre des obstacles, créant des accumulations.'),
('nature', 4, 'Comment s''appelle la théorie qui explique le mouvement des plaques tectoniques ?', 'La tectonique des plaques', ARRAY['La dérive des continents uniquement', 'La théorie de la contraction', 'La théorie de l''expansion terrestre'], 'fr', true, 'La tectonique des plaques, développée dans les années 1960, explique les mouvements des plaques lithosphériques.'),
('nature', 4, 'Quel est le phénomène qui crée les cheminées de fée en géologie ?', 'L''érosion différentielle protégeant la roche tendre sous un chapeau dur', ARRAY['Les éruptions volcaniques', 'Les tremblements de terre', 'La cristallisation du sel'], 'fr', true, 'Les cheminées de fée se forment quand une roche dure protège la roche tendre en dessous de l''érosion.'),
('nature', 4, 'Quelle est la fonction des stomates dans les feuilles ?', 'Réguler les échanges gazeux et la transpiration', ARRAY['Absorber la lumière', 'Stocker les nutriments', 'Produire la chlorophylle'], 'fr', true, 'Les stomates sont de minuscules pores qui permettent l''entrée du CO2 et la sortie de l''eau et de l''O2.'),
('nature', 4, 'Comment appelle-t-on le phénomène où les rivières souterraines dissolvent le calcaire ?', 'La karstification', ARRAY['L''érosion éolienne', 'La glaciation', 'La latérisation'], 'fr', true, 'La karstification crée des grottes, dolines et rivières souterraines par dissolution chimique du calcaire.'),
('nature', 4, 'Quel est l''indice qui mesure la diversité biologique d''un écosystème ?', 'L''indice de Shannon', ARRAY['L''indice de Richter', 'L''indice de Mohs', 'L''indice de Beaufort'], 'fr', true, 'L''indice de Shannon prend en compte la richesse spécifique et l''équitabilité pour mesurer la biodiversité.'),
('nature', 4, 'Quelle est la particularité des cénotes au Mexique ?', 'Ce sont des puits naturels formés par l''effondrement de calcaire au-dessus de rivières souterraines', ARRAY['Ce sont des volcans sous-marins', 'Ce sont des lacs salés', 'Ce sont des geysers tropicaux'], 'fr', true, 'Les cénotes sont des gouffres karstiques remplis d''eau douce, sacrés pour les Mayas.'),
('nature', 4, 'Comment appelle-t-on le phénomène de recul des glaciers dû au réchauffement climatique ?', 'Le retrait glaciaire', ARRAY['La débâcle', 'La transgression', 'La cryoclastie'], 'fr', true, 'Le retrait glaciaire est la diminution de la taille des glaciers causée par un bilan de masse négatif.'),
('nature', 4, 'Quel est le processus par lequel les organismes marins fixent le carbone dans leurs coquilles ?', 'La biominéralisation', ARRAY['La photosynthèse', 'La chimiosynthèse', 'La fermentation'], 'fr', true, 'La biominéralisation est le processus par lequel les organismes créent des structures minérales comme le carbonate de calcium.'),
('nature', 4, 'Quelle est la différence entre un cyclone, un ouragan et un typhon ?', 'C''est le même phénomène, nommé différemment selon la région', ARRAY['Ils ont des vitesses de vent différentes', 'L''un est terrestre, l''autre marin', 'Ils tournent dans des sens différents'], 'fr', true, 'Cyclone (océan Indien), ouragan (Atlantique) et typhon (Pacifique ouest) désignent le même type de tempête tropicale.'),
('nature', 4, 'Comment appelle-t-on la période de l''histoire de la Terre où la vie complexe a explosé ?', 'L''explosion cambrienne', ARRAY['Le Précambrien', 'Le Jurassique', 'Le Carbonifère'], 'fr', true, 'L''explosion cambrienne, il y a environ 540 millions d''années, a vu l''apparition rapide de la plupart des embranchements animaux.');
INSERT INTO questions (category, difficulty, question_text, correct_answer, wrong_answers, language, is_active, explanation) VALUES
('nature', 5, 'Qu''est-ce que l''effet Coriolis ?', 'La déviation des masses d''air et d''eau due à la rotation de la Terre', ARRAY['L''attraction gravitationnelle de la Lune', 'La réfraction de la lumière dans l''atmosphère', 'Le réchauffement inégal des océans'], 'fr', true, 'L''effet Coriolis dévie les vents vers la droite dans l''hémisphère nord et vers la gauche dans l''hémisphère sud.'),
('nature', 5, 'Qu''est-ce que la thermocline dans l''océan ?', 'Une couche de transition rapide de température entre les eaux de surface et les eaux profondes', ARRAY['La surface de l''eau la plus chaude', 'Le fond de l''océan le plus froid', 'Une couche de sel concentré'], 'fr', true, 'La thermocline est une zone où la température chute rapidement avec la profondeur, séparant les eaux chaudes de surface des eaux froides profondes.'),
('nature', 5, 'Quel est le mécanisme principal de la convection mantellique ?', 'Le chauffage par le noyau et le refroidissement par la surface créent des cellules de convection', ARRAY['La rotation de la Terre', 'L''attraction lunaire', 'Les marées internes'], 'fr', true, 'La convection mantellique est le moteur principal de la tectonique des plaques, entraînée par les différences de température.'),
('nature', 5, 'Comment s''appelle le phénomène de rétroaction positive entre la fonte des glaces et le réchauffement ?', 'La rétroaction albédo-glace', ARRAY['L''effet de serre renforcé', 'L''oscillation arctique', 'Le forçage radiatif'], 'fr', true, 'Quand la glace fond, la surface plus sombre absorbe plus de chaleur, accélérant la fonte dans un cercle vicieux.'),
('nature', 5, 'Qu''est-ce que le point de basculement climatique (tipping point) ?', 'Un seuil au-delà duquel un changement devient irréversible et auto-entretenu', ARRAY['La température maximale annuelle', 'Le point de fusion de la glace', 'La concentration maximale de CO2 supportable'], 'fr', true, 'Les points de basculement sont des seuils critiques du système climatique dont le franchissement déclenche des changements en cascade.'),
('nature', 5, 'Quel est le rôle des diatomées dans le cycle du carbone océanique ?', 'Elles fixent le CO2 par photosynthèse et le transportent vers les fonds marins en mourant', ARRAY['Elles produisent du méthane', 'Elles dissolvent le carbonate de calcium', 'Elles libèrent de l''azote'], 'fr', true, 'Les diatomées sont responsables d''environ 20% de la fixation mondiale de carbone et contribuent à la pompe biologique.'),
('nature', 5, 'Comment s''appelle le phénomène d''oscillation climatique dans l''Atlantique Nord ?', 'L''Oscillation Nord-Atlantique (NAO)', ARRAY['El Niño', 'La Niña', 'L''oscillation de Madden-Julian'], 'fr', true, 'La NAO est une variation de la différence de pression entre l''anticyclone des Açores et la dépression d''Islande.'),
('nature', 5, 'Quelle est la relation entre l''isostasie et le rebond post-glaciaire ?', 'La croûte terrestre remonte après la disparition de la charge glaciaire', ARRAY['Les glaciers s''enfoncent dans le sol', 'Les montagnes grandissent pendant les glaciations', 'Les océans se rétractent après les glaciations'], 'fr', true, 'L''isostasie est l''équilibre gravitationnel de la croûte : après la fonte des glaciers, la terre allégée remonte lentement.'),
('nature', 5, 'Qu''est-ce que la pompe à soluté biologique dans les océans ?', 'Le transport de carbone organique de la surface vers les profondeurs par les organismes', ARRAY['La circulation thermohaline', 'L''upwelling côtier', 'La dissolution du sel'], 'fr', true, 'La pompe biologique transfère le carbone fixé en surface par le phytoplancton vers les profondeurs via les déchets organiques.'),
('nature', 5, 'Quel est le mécanisme de formation des ophiolites ?', 'Ce sont des fragments de croûte océanique charriés sur les continents lors de la collision des plaques', ARRAY['Ce sont des roches volcaniques continentales', 'Ce sont des dépôts glaciaires anciens', 'Ce sont des roches formées par impact météoritique'], 'fr', true, 'Les ophiolites sont des lambeaux de lithosphère océanique obductés sur les continents, témoins de la fermeture d''anciens océans.'),
('nature', 5, 'Comment s''appelle le concept de services écosystémiques de régulation ?', 'Les bénéfices indirects des écosystèmes comme la purification de l''eau et la régulation du climat', ARRAY['La production de nourriture', 'Le tourisme naturel', 'L''extraction de ressources'], 'fr', true, 'Les services de régulation incluent la pollinisation, la filtration de l''eau, la séquestration du carbone et le contrôle des inondations.'),
('nature', 5, 'Quel est le principe de la théorie de Milankovitch sur les glaciations ?', 'Les variations cycliques de l''orbite terrestre modifient le rayonnement solaire reçu', ARRAY['Les éruptions volcaniques bloquent le soleil', 'Les courants océaniques changent de direction', 'Le soleil a des cycles d''activité irréguliers'], 'fr', true, 'Les cycles de Milankovitch incluent l''excentricité orbitale, l''obliquité et la précession des équinoxes.'),
('nature', 5, 'Qu''est-ce que la zonation altitudinale des écosystèmes ?', 'La succession de biomes différents selon l''altitude sur une montagne', ARRAY['La répartition des sols selon la longitude', 'La distribution des espèces selon la latitude uniquement', 'La variation de la salinité avec la profondeur'], 'fr', true, 'En montagne, on observe une succession de biomes (forêt, prairie alpine, nival) comparable à la zonation latitudinale.'),
('nature', 5, 'Comment s''appelle le phénomène de piégeage du CO2 atmosphérique par l''altération chimique des silicates ?', 'L''altération des silicates (weathering)', ARRAY['La séquestration biologique', 'La dissolution océanique', 'La carbonatation industrielle'], 'fr', true, 'L''altération chimique des silicates est un puits de CO2 naturel majeur qui régule le climat sur des millions d''années.'),
('nature', 5, 'Quel est le concept de l''hypothèse Gaïa ?', 'La Terre et ses écosystèmes fonctionnent comme un système autorégulé', ARRAY['La Terre est un organisme vivant', 'La vie n''existe que sur Terre', 'Les continents se déplacent de manière aléatoire'], 'fr', true, 'L''hypothèse Gaïa, proposée par James Lovelock, suggère que les organismes vivants interagissent avec l''environnement pour maintenir des conditions favorables à la vie.'),
('nature', 5, 'Qu''est-ce que le phénomène de subsidence atmosphérique dans les cellules de Hadley ?', 'La descente d''air sec aux latitudes subtropicales créant les déserts', ARRAY['La montée d''air humide à l''équateur', 'Les vents d''altitude', 'Le refroidissement des pôles'], 'fr', true, 'Dans les cellules de Hadley, l''air chaud monte à l''équateur et redescend vers 30° de latitude, asséchant ces zones.'),
('nature', 5, 'Comment appelle-t-on les masses d''eau caractérisées par leur température et salinité dans l''océan profond ?', 'Les masses d''eau', ARRAY['Les courants de surface', 'Les thermoclines', 'Les gyres océaniques'], 'fr', true, 'Les masses d''eau comme l''Eau Profonde Nord-Atlantique gardent leurs propriétés de température et salinité sur des milliers de km.'),
('nature', 5, 'Quel est le rôle du DMS (diméthylsulfure) produit par le phytoplancton dans la formation des nuages ?', 'Le DMS oxydé forme des noyaux de condensation qui favorisent la formation des nuages', ARRAY['Le DMS absorbe la lumière solaire', 'Le DMS détruit les nuages', 'Le DMS acidifie les océans'], 'fr', true, 'Le DMS émis par le phytoplancton contribue à la formation de nuages, jouant un rôle dans la régulation du climat.'),
('nature', 5, 'Qu''est-ce que la succession allogenique en écologie ?', 'Un changement de communauté provoqué par des facteurs externes comme le climat ou la géologie', ARRAY['Un changement provoqué par les organismes eux-mêmes', 'Une extinction de masse', 'Une adaptation rapide des espèces'], 'fr', true, 'Contrairement à la succession autogénique (interne), la succession allogénique est entraînée par des forces externes.'),
('nature', 5, 'Comment s''appelle le phénomène de dégazage de CO2 par les volcans sur le temps géologique ?', 'Le cycle géologique du carbone', ARRAY['La respiration planétaire', 'L''oxygénation atmosphérique', 'La carbonification volcanique'], 'fr', true, 'Le dégazage volcanique libère du CO2 piégé dans le manteau, alimentant le cycle du carbone sur des millions d''années.'),
('nature', 5, 'Quel est le principe de l''effet de serre radiatif ?', 'Les gaz à effet de serre absorbent et réémettent le rayonnement infrarouge terrestre', ARRAY['Les gaz bloquent la lumière visible du soleil', 'Les nuages réfléchissent toute la chaleur', 'L''atmosphère conduit la chaleur vers le sol'], 'fr', true, 'Les gaz à effet de serre sont transparents au rayonnement solaire mais absorbent le rayonnement infrarouge émis par la Terre.'),
('nature', 5, 'Qu''est-ce que le phénomène d''anoxie océanique ?', 'L''épuisement de l''oxygène dissous dans les eaux profondes de l''océan', ARRAY['L''excès d''oxygène dans l''eau', 'La désalinisation des océans', 'Le refroidissement brutal des eaux'], 'fr', true, 'L''anoxie océanique peut provoquer des zones mortes où la vie marine ne peut pas survivre.'),
('nature', 5, 'Comment s''appelle le phénomène de transport éolien de poussières sahariennes fertilisant l''Amazonie ?', 'La fertilisation transsaharienne', ARRAY['La mousson africaine', 'Le sirocco amazonien', 'Le transport fluvial transatlantique'], 'fr', true, 'Des millions de tonnes de poussières du Sahara traversent l''Atlantique chaque année, apportant du phosphore à l''Amazonie.'),
('nature', 5, 'Quel est le concept de la sixième extinction de masse ?', 'La perte accélérée de biodiversité causée par les activités humaines actuelles', ARRAY['L''extinction des dinosaures', 'Une extinction future hypothétique dans 1 million d''années', 'La fin de l''ère glaciaire'], 'fr', true, 'Le taux d''extinction actuel est estimé à 100-1000 fois supérieur au taux naturel, justifiant le terme de sixième extinction.'),
('nature', 5, 'Qu''est-ce que le gradient géothermique ?', 'L''augmentation de la température avec la profondeur dans la croûte terrestre', ARRAY['La variation de température entre les saisons', 'La différence de chaleur entre l''équateur et les pôles', 'Le refroidissement de la lave en surface'], 'fr', true, 'Le gradient géothermique moyen est d''environ 25-30°C par kilomètre de profondeur dans la croûte terrestre.');
INSERT INTO questions (category, difficulty, question_text, correct_answer, wrong_answers, language, is_active, explanation) VALUES
('nature', 1, 'What gas do plants produce during photosynthesis?', 'Oxygen', ARRAY['Carbon dioxide', 'Nitrogen', 'Hydrogen'], 'en', true, 'Plants absorb CO2 and produce oxygen through photosynthesis.'),
('nature', 1, 'What is the largest ocean on Earth?', 'Pacific Ocean', ARRAY['Atlantic Ocean', 'Indian Ocean', 'Arctic Ocean'], 'en', true, 'The Pacific Ocean covers about one-third of the Earth''s surface.'),
('nature', 1, 'How many seasons are there in a year?', '4', ARRAY['2', '3', '6'], 'en', true, 'The four seasons are spring, summer, autumn (fall), and winter.'),
('nature', 1, 'What is rain?', 'Water falling from clouds', ARRAY['Steam from the ground', 'Dust from space', 'Frozen air'], 'en', true, 'Rain is water that condenses in clouds and falls as droplets.'),
('nature', 1, 'What makes leaves green?', 'Chlorophyll', ARRAY['Oxygen', 'Water', 'Sunlight'], 'en', true, 'Chlorophyll is the green pigment in leaves that helps plants make food from sunlight.'),
('nature', 1, 'What star is closest to Earth?', 'The Sun', ARRAY['Alpha Centauri', 'Sirius', 'Polaris'], 'en', true, 'The Sun is a star located about 150 million kilometers from Earth.'),
('nature', 1, 'What is a volcano?', 'A mountain that can erupt with lava', ARRAY['A very tall mountain', 'A deep hole in the ground', 'A type of earthquake'], 'en', true, 'A volcano is an opening in the Earth''s crust where molten rock (lava) can erupt.'),
('nature', 1, 'What part of a plant absorbs water from the soil?', 'Roots', ARRAY['Leaves', 'Stem', 'Flowers'], 'en', true, 'Roots absorb water and nutrients from the soil to nourish the plant.'),
('nature', 1, 'What is the longest river in the world?', 'The Nile', ARRAY['The Amazon', 'The Mississippi', 'The Yangtze'], 'en', true, 'The Nile River is approximately 6,650 km long, flowing through northeastern Africa.'),
('nature', 1, 'What causes ocean tides?', 'The Moon''s gravity', ARRAY['Wind', 'Earthquakes', 'Ocean currents'], 'en', true, 'The gravitational pull of the Moon is the primary cause of ocean tides.'),
('nature', 1, 'What is a rainbow?', 'An arc of colors formed by light passing through water droplets', ARRAY['A painted cloud', 'A type of lightning', 'A reflection of the ground'], 'en', true, 'Rainbows appear when sunlight is refracted by raindrops, splitting light into its colors.'),
('nature', 1, 'What type of forest is found near the equator?', 'Tropical rainforest', ARRAY['Coniferous forest', 'Temperate forest', 'Tundra'], 'en', true, 'Tropical rainforests are found near the equator where it is warm and wet year-round.'),
('nature', 1, 'At what temperature does water freeze?', '0 degrees Celsius', ARRAY['10 degrees Celsius', '100 degrees Celsius', '-10 degrees Celsius'], 'en', true, 'Water freezes at 0°C (32°F), changing from liquid to solid state.'),
('nature', 1, 'What is the tallest mountain in the world?', 'Mount Everest', ARRAY['K2', 'Mont Blanc', 'Kilimanjaro'], 'en', true, 'Mount Everest stands at 8,849 meters in the Himalayan mountain range.'),
('nature', 1, 'What do bees produce?', 'Honey', ARRAY['Milk', 'Sugar', 'Wax only'], 'en', true, 'Bees produce honey from the nectar of flowers.'),
('nature', 1, 'In which season do leaves fall from trees?', 'Autumn', ARRAY['Winter', 'Spring', 'Summer'], 'en', true, 'In autumn, leaves change color and fall from deciduous trees.'),
('nature', 1, 'What gas do humans breathe out?', 'Carbon dioxide', ARRAY['Oxygen', 'Nitrogen', 'Hydrogen'], 'en', true, 'We breathe in oxygen and breathe out carbon dioxide (CO2).'),
('nature', 1, 'What is the largest desert on Earth?', 'The Sahara', ARRAY['The Gobi', 'The Arabian Desert', 'The Kalahari'], 'en', true, 'The Sahara Desert covers approximately 9 million square kilometers in North Africa.'),
('nature', 1, 'What energy comes from the wind?', 'Wind energy', ARRAY['Solar energy', 'Hydropower', 'Geothermal energy'], 'en', true, 'Wind energy is produced by wind turbines that convert wind into electricity.'),
('nature', 1, 'What is the largest land animal?', 'The elephant', ARRAY['The giraffe', 'The rhinoceros', 'The hippopotamus'], 'en', true, 'The African elephant is the largest land animal, weighing up to 6 tons.'),
('nature', 1, 'What color is lava when it flows?', 'Red-orange', ARRAY['Blue', 'Green', 'Black'], 'en', true, 'Flowing lava is red-orange due to its extremely high temperature.'),
('nature', 1, 'What tree produces acorns?', 'Oak tree', ARRAY['Pine tree', 'Birch tree', 'Maple tree'], 'en', true, 'Oak trees produce acorns, which are food for many animals.'),
('nature', 1, 'What is a large floating chunk of ice in the ocean called?', 'An iceberg', ARRAY['A glacier', 'An ice shelf', 'A floe'], 'en', true, 'An iceberg is a large piece of ice that has broken off a glacier and floats in the ocean.'),
('nature', 1, 'Why is Earth called the "Blue Planet"?', 'Because 71% of its surface is covered by water', ARRAY['Because the sky is blue', 'Because of blue rocks', 'Because of blue plants'], 'en', true, 'Earth appears blue from space because most of its surface is covered by oceans.'),
('nature', 1, 'What causes earthquakes?', 'Movement of tectonic plates', ARRAY['Strong winds', 'Heavy rain', 'Volcanic gases'], 'en', true, 'Earthquakes are caused by the sudden movement of tectonic plates along fault lines.'),
('nature', 1, 'What is the coldest continent?', 'Antarctica', ARRAY['The Arctic', 'Europe', 'Asia'], 'en', true, 'Antarctica is the coldest continent, with temperatures that can drop below -80°C.'),
('nature', 1, 'What natural phenomenon produces lightning?', 'A thunderstorm', ARRAY['A tornado', 'A hurricane', 'An earthquake'], 'en', true, 'Lightning is an electrical discharge that occurs during thunderstorms.'),
('nature', 1, 'What do animals that sleep all winter do?', 'Hibernate', ARRAY['Migrate', 'Camouflage', 'Shed'], 'en', true, 'Hibernation is a state of deep sleep that some animals enter during winter to conserve energy.'),
('nature', 1, 'What frozen water falls from the sky as white flakes?', 'Snow', ARRAY['Hail', 'Frost', 'Sleet'], 'en', true, 'Snow is formed when water vapor in clouds freezes into ice crystals.'),
('nature', 1, 'What is at the center of the Earth?', 'A very hot core', ARRAY['Water', 'Empty space', 'Ice'], 'en', true, 'The Earth''s core is made primarily of iron and nickel at extremely high temperatures.'),
('nature', 1, 'What is the most common gas in the air we breathe?', 'Nitrogen', ARRAY['Oxygen', 'Carbon dioxide', 'Hydrogen'], 'en', true, 'The atmosphere is about 78% nitrogen and 21% oxygen.'),
('nature', 1, 'What raw material comes from trees?', 'Wood', ARRAY['Metal', 'Plastic', 'Glass'], 'en', true, 'Wood is a renewable natural resource produced by trees.'),
('nature', 1, 'Where do fish live?', 'In water', ARRAY['On land', 'In trees', 'In sand'], 'en', true, 'Fish breathe underwater using their gills.'),
('nature', 1, 'What forms stalactites in caves?', 'Dripping water carrying dissolved minerals', ARRAY['Underground wind', 'Volcanic heat', 'Earthquakes'], 'en', true, 'Stalactites form from calcium carbonate deposited by water dripping from cave ceilings.'),
('nature', 1, 'What is the water cycle?', 'The continuous movement of water through evaporation, condensation, and precipitation', ARRAY['Water flowing in rivers only', 'Rain falling once', 'Water disappearing underground'], 'en', true, 'The water cycle describes how water moves between the atmosphere, land, and oceans.'),
('nature', 1, 'What is a flat, grassy area with few trees called?', 'A prairie or grassland', ARRAY['A forest', 'A marsh', 'A jungle'], 'en', true, 'Prairies or grasslands are ecosystems dominated by grasses with few or no trees.'),
('nature', 1, 'What insect produces silk?', 'The silkworm', ARRAY['The spider', 'The caterpillar', 'The butterfly'], 'en', true, 'The silkworm (Bombyx mori) produces silk thread to form its cocoon.'),
('nature', 1, 'How do birds travel long distances in autumn?', 'They migrate', ARRAY['They hibernate', 'They hide', 'They swim'], 'en', true, 'Migration is the seasonal movement of birds to warmer regions.'),
('nature', 1, 'What makes hail fall from the sky?', 'Water droplets freezing in storm clouds', ARRAY['Snow melting and refreezing', 'Rocks from space', 'Volcanic ash'], 'en', true, 'Hail forms when water droplets are carried up by strong updrafts and freeze in storm clouds.'),
('nature', 1, 'What is a low cloud that reduces visibility near the ground?', 'Fog', ARRAY['Smog', 'Dew', 'Frost'], 'en', true, 'Fog is essentially a cloud at ground level that reduces visibility to less than one kilometer.'),
('nature', 1, 'What is sand on beaches mainly made of?', 'Tiny grains of rock', ARRAY['Salt', 'Shells only', 'Coral only'], 'en', true, 'Beach sand is mostly made of quartz grains from the erosion of rocks.'),
('nature', 1, 'What is a baby frog called?', 'A tadpole', ARRAY['A fry', 'A larva', 'A chick'], 'en', true, 'A tadpole is the larval stage of a frog, living in water before transforming.'),
('nature', 1, 'What flower is the symbol of Japan?', 'Cherry blossom', ARRAY['Rose', 'Tulip', 'Sunflower'], 'en', true, 'The cherry blossom (sakura) is an iconic symbol of Japanese culture.'),
('nature', 1, 'What planet is known as the "Red Planet"?', 'Mars', ARRAY['Venus', 'Jupiter', 'Saturn'], 'en', true, 'Mars appears red due to iron oxide (rust) on its surface.'),
('nature', 1, 'What happens to water when it boils?', 'It turns into steam (gas)', ARRAY['It turns into ice', 'It disappears', 'It becomes heavier'], 'en', true, 'Water boils at 100°C and turns into water vapor or steam.'),
('nature', 1, 'What is the main source of energy for life on Earth?', 'The Sun', ARRAY['The Moon', 'Wind', 'Volcanoes'], 'en', true, 'The Sun provides the energy that drives photosynthesis and most life on Earth.'),
('nature', 1, 'What are the Northern Lights?', 'Colorful lights in the sky near the poles', ARRAY['Reflections of city lights', 'Lightning in the clouds', 'Shooting stars'], 'en', true, 'The Northern Lights (aurora borealis) are caused by solar particles interacting with Earth''s atmosphere.'),
('nature', 1, 'What do we call the place where a river begins?', 'The source', ARRAY['The mouth', 'The delta', 'The estuary'], 'en', true, 'The source of a river is its starting point, often a spring, lake, or glacier.'),
('nature', 1, 'What type of animal lives both on land and in water?', 'An amphibian', ARRAY['A reptile', 'A mammal', 'A fish'], 'en', true, 'Amphibians like frogs and salamanders can live both on land and in water.'),
('nature', 1, 'What is the driest place on Earth?', 'The Atacama Desert', ARRAY['The Sahara Desert', 'Antarctica', 'The Gobi Desert'], 'en', true, 'The Atacama Desert in Chile is the driest non-polar place on Earth, with some areas receiving no rain for years.');
INSERT INTO questions (category, difficulty, question_text, correct_answer, wrong_answers, language, is_active, explanation) VALUES
('nature', 2, 'What is the tallest type of tree in the world?', 'Redwood (Sequoia)', ARRAY['Baobab', 'Eucalyptus', 'Douglas Fir'], 'en', true, 'The coast redwood (Hyperion) is the tallest known tree, measuring over 115 meters.'),
('nature', 2, 'What layer of the atmosphere protects us from UV rays?', 'The ozone layer', ARRAY['The troposphere', 'The mesosphere', 'The thermosphere'], 'en', true, 'The ozone layer in the stratosphere filters harmful ultraviolet radiation from the Sun.'),
('nature', 2, 'What type of rock is formed from cooled lava?', 'Igneous rock', ARRAY['Sedimentary rock', 'Metamorphic rock', 'Limestone'], 'en', true, 'Igneous rocks form when lava or magma cools and solidifies.'),
('nature', 2, 'What is the largest coral reef system in the world?', 'The Great Barrier Reef', ARRAY['The Belize Barrier Reef', 'The New Caledonia Reef', 'The Red Sea Reef'], 'en', true, 'The Great Barrier Reef in Australia stretches over 2,300 kilometers.'),
('nature', 2, 'What process turns a caterpillar into a butterfly?', 'Metamorphosis', ARRAY['Mutation', 'Molting', 'Evolution'], 'en', true, 'Metamorphosis is the process by which a caterpillar transforms into a chrysalis and then a butterfly.'),
('nature', 2, 'What hardest natural mineral is rated 10 on the Mohs scale?', 'Diamond', ARRAY['Ruby', 'Quartz', 'Sapphire'], 'en', true, 'Diamond has a hardness of 10 on the Mohs scale, making it the hardest natural mineral.'),
('nature', 2, 'What spinning column of air extends from a cloud to the ground?', 'A tornado', ARRAY['A hurricane', 'A typhoon', 'A monsoon'], 'en', true, 'A tornado is a violently rotating column of air that extends from a thunderstorm cloud to the ground.'),
('nature', 2, 'What type of forest dominates in Scandinavia?', 'Taiga (boreal forest)', ARRAY['Tropical forest', 'Mediterranean forest', 'Mangrove'], 'en', true, 'The taiga is a boreal coniferous forest covering vast areas of Scandinavia and Siberia.'),
('nature', 2, 'What is permanently frozen ground called?', 'Permafrost', ARRAY['Glacier', 'Ice sheet', 'Tundra'], 'en', true, 'Permafrost is ground that remains frozen for at least two consecutive years.'),
('nature', 2, 'What is the main cause of coastal erosion?', 'Waves', ARRAY['Wind', 'Rain', 'Earthquakes'], 'en', true, 'Waves are the primary agent of coastal erosion, sculpting cliffs and beaches.'),
('nature', 2, 'What natural disaster is caused by an underwater earthquake?', 'A tsunami', ARRAY['A hurricane', 'A cyclone', 'A river flood'], 'en', true, 'A tsunami is a series of giant waves caused by a sudden displacement of the ocean floor.'),
('nature', 2, 'What type of rocks are formed by the accumulation of sediments?', 'Sedimentary rocks', ARRAY['Igneous rocks', 'Metamorphic rocks', 'Crystalline rocks'], 'en', true, 'Sedimentary rocks form by the accumulation and compaction of sediments over time.'),
('nature', 2, 'What rock is used to make cement?', 'Limestone', ARRAY['Granite', 'Basalt', 'Marble'], 'en', true, 'Limestone is the main raw material used in the production of cement.'),
('nature', 2, 'What animal is the primary pollinator of flowers?', 'The bee', ARRAY['The butterfly', 'The hummingbird', 'The fly'], 'en', true, 'Bees are responsible for pollinating about 80% of flowering plants.'),
('nature', 2, 'What is a wetland area with salt-water adapted trees called?', 'A mangrove', ARRAY['A marsh', 'A peat bog', 'A swamp'], 'en', true, 'Mangroves are tropical coastal forests with trees adapted to saltwater conditions.'),
('nature', 2, 'Which Italian volcano famously destroyed Pompeii?', 'Vesuvius', ARRAY['Etna', 'Stromboli', 'Vulcano'], 'en', true, 'Mount Vesuvius destroyed Pompeii and Herculaneum in its eruption in 79 AD.'),
('nature', 2, 'Where does fresh river water meet salt water from the sea?', 'An estuary', ARRAY['A delta', 'A fjord', 'A bay'], 'en', true, 'An estuary is a transition zone where fresh water from a river mixes with salt water from the sea.'),
('nature', 2, 'What energy source uses heat from inside the Earth?', 'Geothermal energy', ARRAY['Solar energy', 'Wind energy', 'Tidal energy'], 'en', true, 'Geothermal energy harnesses the natural heat from within the Earth.'),
('nature', 2, 'What greenhouse gas is most emitted by human activities?', 'Carbon dioxide (CO2)', ARRAY['Methane', 'Nitrous oxide', 'Ozone'], 'en', true, 'CO2 accounts for about 75% of human-caused greenhouse gas emissions.'),
('nature', 2, 'What is the biome with the most biodiversity on Earth?', 'Tropical rainforest', ARRAY['Savanna', 'Temperate forest', 'Coral reef'], 'en', true, 'Tropical rainforests harbor more than 50% of all terrestrial plant and animal species.'),
('nature', 2, 'What is the outermost layer of the Earth called?', 'The crust', ARRAY['The mantle', 'The outer core', 'The inner core'], 'en', true, 'The Earth''s crust is the thin outer solid layer, ranging from 5 to 70 km thick.'),
('nature', 2, 'What is a long period without rain called?', 'A drought', ARRAY['A heatwave', 'An anticyclone', 'A monsoon'], 'en', true, 'A drought is a prolonged period of below-average precipitation that affects ecosystems and agriculture.'),
('nature', 2, 'What continent has the largest tropical rainforest?', 'South America', ARRAY['Africa', 'Asia', 'Oceania'], 'en', true, 'The Amazon rainforest in South America is the largest tropical rainforest in the world.'),
('nature', 2, 'What is the dark, organic-rich layer of soil called?', 'Humus', ARRAY['Clay', 'Silt', 'Sand'], 'en', true, 'Humus is the top layer of soil formed by the decomposition of organic matter.'),
('nature', 2, 'What is the process by which water evaporates from leaves?', 'Transpiration', ARRAY['Photosynthesis', 'Respiration', 'Osmosis'], 'en', true, 'Transpiration is the process by which water passes from plants to the atmosphere through leaves.'),
('nature', 2, 'What is the main natural greenhouse gas in the atmosphere?', 'Water vapor', ARRAY['CO2', 'Methane', 'Ozone'], 'en', true, 'Water vapor is the most abundant greenhouse gas in Earth''s atmosphere.'),
('nature', 2, 'What phenomenon describes the gradual warming of the planet?', 'Global warming', ARRAY['Natural greenhouse effect', 'Thermal inversion', 'El Nino'], 'en', true, 'Global warming refers to the increase in Earth''s average temperature caused by human activities.'),
('nature', 2, 'What is the deepest point in the ocean?', 'The Mariana Trench', ARRAY['The Puerto Rico Trench', 'The Java Trench', 'The Tonga Trench'], 'en', true, 'The Mariana Trench in the Pacific Ocean reaches approximately 11,034 meters deep.'),
('nature', 2, 'What type of solar panel converts sunlight directly into electricity?', 'Photovoltaic panel', ARRAY['Thermal panel', 'Reflector panel', 'Infrared panel'], 'en', true, 'Photovoltaic panels convert sunlight directly into electricity using semiconductor materials.'),
('nature', 2, 'What luminous phenomenon can be seen in polar skies?', 'Aurora borealis (Northern Lights)', ARRAY['Rainbow', 'Solar halo', 'Meteor shower'], 'en', true, 'Auroras are caused by solar particles interacting with Earth''s atmosphere near the magnetic poles.'),
('nature', 2, 'What is the main role of forests in the carbon cycle?', 'Absorbing CO2', ARRAY['Producing CO2', 'Storing nitrogen', 'Evaporating water'], 'en', true, 'Forests are carbon sinks: they absorb CO2 through photosynthesis and store it in wood.'),
('nature', 2, 'What is the phenomenon of species disappearing from the Earth?', 'Extinction', ARRAY['Migration', 'Adaptation', 'Evolution'], 'en', true, 'Extinction is the complete disappearance of a species, a process often accelerated by human activities.'),
('nature', 2, 'What is the largest active volcano in Europe?', 'Mount Etna', ARRAY['Mount Vesuvius', 'Stromboli', 'Eyjafjallajokull'], 'en', true, 'Mount Etna in Sicily rises to about 3,357 meters and erupts regularly.'),
('nature', 2, 'What is the difference between a river and a stream?', 'A river is larger and carries more water', ARRAY['A stream is saltwater', 'A river flows underground', 'A stream is faster'], 'en', true, 'Rivers are larger waterways that typically flow into the sea, while streams are smaller tributaries.'),
('nature', 2, 'What is the largest freshwater lake in the world by surface area?', 'Lake Superior', ARRAY['Lake Victoria', 'Lake Baikal', 'Lake Huron'], 'en', true, 'Lake Superior covers about 82,100 square kilometers, making it the largest freshwater lake by area.'),
('nature', 2, 'What is the phenomenon of rising water levels in rivers called?', 'A flood or spate', ARRAY['A tide', 'A tidal wave', 'A drought'], 'en', true, 'A flood occurs when a river overflows its banks due to heavy rainfall or snowmelt.'),
('nature', 2, 'What type of climate has hot, dry summers and mild, wet winters?', 'Mediterranean climate', ARRAY['Continental climate', 'Oceanic climate', 'Tropical climate'], 'en', true, 'Mediterranean climate is found in areas like southern Europe, California, and parts of Australia.'),
('nature', 2, 'What is a peat-rich wetland called?', 'A peat bog', ARRAY['A prairie', 'A moor', 'A hedgerow'], 'en', true, 'Peat bogs are wetlands where plant material decomposes very slowly, forming peat over thousands of years.'),
('nature', 2, 'What cold, treeless biome is found in the far north?', 'Tundra', ARRAY['Taiga', 'Steppe', 'Savanna'], 'en', true, 'The tundra is a biome characterized by permanently frozen soil (permafrost) and low-growing vegetation.'),
('nature', 2, 'What ocean current warms the climate of Western Europe?', 'The Gulf Stream', ARRAY['The Humboldt Current', 'The Kuroshio Current', 'The Labrador Current'], 'en', true, 'The Gulf Stream carries warm water from the Gulf of Mexico across the Atlantic, moderating European winters.'),
('nature', 2, 'What is the supercontinent that existed 250 million years ago called?', 'Pangaea', ARRAY['Laurasia', 'Gondwana', 'Rodinia'], 'en', true, 'Pangaea was a supercontinent that contained all the Earth''s landmasses before breaking apart.'),
('nature', 2, 'What process creates ocean waves in the open sea?', 'Wind blowing over the water surface', ARRAY['Earthquakes only', 'The Moon''s gravity only', 'Underwater volcanoes'], 'en', true, 'Most ocean waves are generated by wind transferring energy to the water surface.'),
('nature', 2, 'What is the largest lake in Europe?', 'Lake Ladoga', ARRAY['Lake Geneva', 'Lake Constance', 'Lake Balaton'], 'en', true, 'Lake Ladoga in Russia covers about 17,700 square kilometers.'),
('nature', 2, 'What cyclic weather phenomenon warms Pacific Ocean waters?', 'El Nino', ARRAY['La Nina', 'The Gulf Stream', 'The monsoon'], 'en', true, 'El Nino is an abnormal warming of Pacific waters that disrupts global weather patterns.'),
('nature', 2, 'What is the study of weather called?', 'Meteorology', ARRAY['Geology', 'Ecology', 'Climatology'], 'en', true, 'Meteorology is the scientific study of the atmosphere and short-term weather conditions.'),
('nature', 2, 'What is the main source of renewable energy globally?', 'Hydropower', ARRAY['Solar energy', 'Wind energy', 'Biomass'], 'en', true, 'Hydroelectric power is the most widely used renewable energy source worldwide.'),
('nature', 2, 'What is a soil rich in decomposed organic matter called?', 'Topsoil or humus', ARRAY['Bedrock', 'Subsoil', 'Gravel'], 'en', true, 'Topsoil contains humus, which provides essential nutrients for plant growth.'),
('nature', 2, 'What is the scale used to measure earthquake magnitude?', 'The Richter scale', ARRAY['The Beaufort scale', 'The Saffir-Simpson scale', 'The Mohs scale'], 'en', true, 'The Richter scale measures the magnitude of earthquakes based on seismic wave amplitude.'),
('nature', 2, 'What are the rings visible in a cut tree trunk?', 'Growth rings showing the tree''s age', ARRAY['Decoration patterns', 'Water channels', 'Disease marks'], 'en', true, 'Each ring represents one year of growth, with wider rings indicating favorable growing conditions.');
INSERT INTO questions (category, difficulty, question_text, correct_answer, wrong_answers, language, is_active, explanation) VALUES
('nature', 3, 'What is the pH of pure water?', '7', ARRAY['5', '9', '0'], 'en', true, 'Pure water has a neutral pH of 7, neither acidic nor basic.'),
('nature', 3, 'What is the process by which rocks are broken down by weather called?', 'Weathering', ARRAY['Sedimentation', 'Crystallization', 'Fossilization'], 'en', true, 'Weathering is the process by which rocks are broken down by water, wind, ice, and chemical reactions.'),
('nature', 3, 'What is the main difference between granite and basalt?', 'Their cooling rate', ARRAY['Their color only', 'Their age', 'Their location'], 'en', true, 'Granite cools slowly underground (large crystals) while basalt cools quickly on the surface (fine crystals).'),
('nature', 3, 'What warm ocean current flows across the North Atlantic?', 'The Gulf Stream', ARRAY['El Nino', 'The Kuroshio', 'The Humboldt Current'], 'en', true, 'The Gulf Stream is a warm ocean current that influences the climate of Western Europe.'),
('nature', 3, 'What is the approximate maximum depth of the Mariana Trench?', '11,000 meters', ARRAY['8,000 meters', '15,000 meters', '6,000 meters'], 'en', true, 'The Mariana Trench in the Pacific Ocean reaches approximately 11,034 meters deep.'),
('nature', 3, 'What is the symbiotic relationship between fungi and tree roots called?', 'Mycorrhiza', ARRAY['Parasitism', 'Commensalism', 'Lichen'], 'en', true, 'Mycorrhiza is a mutually beneficial association between fungi and plant roots.'),
('nature', 3, 'What scale measures hurricane intensity?', 'The Saffir-Simpson scale', ARRAY['The Richter scale', 'The Beaufort scale', 'The Mercalli scale'], 'en', true, 'The Saffir-Simpson scale classifies hurricanes from category 1 to 5 based on wind speed.'),
('nature', 3, 'What type of volcano has a cone shape with alternating layers of lava and ash?', 'A stratovolcano', ARRAY['A shield volcano', 'A cinder cone', 'A maar'], 'en', true, 'Stratovolcanoes like Vesuvius and Fuji are formed by alternating lava flows and pyroclastic deposits.'),
('nature', 3, 'What is the phenomenon where oceans absorb CO2 and become more acidic?', 'Ocean acidification', ARRAY['Eutrophication', 'Salinization', 'Deoxygenation'], 'en', true, 'Ocean acidification is caused by the absorption of atmospheric CO2, threatening shell-forming organisms.'),
('nature', 3, 'What is the process of soil formation from bedrock called?', 'Pedogenesis', ARRAY['Lithogenesis', 'Diagenesis', 'Orogenesis'], 'en', true, 'Pedogenesis is the set of physical, chemical, and biological processes that transform rock into soil.'),
('nature', 3, 'What is the transition zone between two ecosystems called?', 'An ecotone', ARRAY['A biotope', 'A biocenosis', 'An ecozone'], 'en', true, 'An ecotone is an ecological transition zone between two adjacent biomes or ecosystems.'),
('nature', 3, 'What type of cloud is associated with severe thunderstorms?', 'Cumulonimbus', ARRAY['Cirrus', 'Stratus', 'Altocumulus'], 'en', true, 'Cumulonimbus clouds can reach 15 km high and produce thunderstorms, heavy rain, and hail.'),
('nature', 3, 'What metamorphic rock comes from the transformation of limestone?', 'Marble', ARRAY['Slate', 'Gneiss', 'Schist'], 'en', true, 'Marble forms when limestone recrystallizes under heat and pressure.'),
('nature', 3, 'How do dandelion seeds primarily spread?', 'Wind (anemochory)', ARRAY['Water (hydrochory)', 'Animals (zoochory)', 'Gravity (barochory)'], 'en', true, 'Dandelion seeds have feathery structures (pappus) that allow them to be carried by the wind.'),
('nature', 3, 'What is the upwelling of cold, deep water to the ocean surface called?', 'Upwelling', ARRAY['Downwelling', 'Thermocline', 'Deep current'], 'en', true, 'Upwelling brings cold, nutrient-rich water to the surface, supporting abundant marine life.'),
('nature', 3, 'What geological feature makes Iceland unique?', 'It sits on a mid-ocean ridge', ARRAY['It is on a single plate', 'It has no volcanoes', 'It is entirely granite'], 'en', true, 'Iceland is one of the rare places where the Mid-Atlantic Ridge emerges above the water surface.'),
('nature', 3, 'What is the ability of an ecosystem to recover after a disturbance called?', 'Resilience', ARRAY['Resistance', 'Succession', 'Regeneration'], 'en', true, 'Ecological resilience is the capacity of an ecosystem to recover after a stress or disturbance.'),
('nature', 3, 'What is the main natural source of methane emissions?', 'Wetlands', ARRAY['Volcanoes', 'Oceans', 'Forests'], 'en', true, 'Wetlands are the largest natural source of methane due to anaerobic decomposition of organic matter.'),
('nature', 3, 'What geological process creates mountain ranges?', 'Orogeny', ARRAY['Erosion', 'Subduction alone', 'Volcanism'], 'en', true, 'Orogeny is the process of mountain building through tectonic plate collision.'),
('nature', 3, 'What are microscopic organisms floating in water collectively called?', 'Plankton', ARRAY['Nekton', 'Benthos', 'Neuston'], 'en', true, 'Plankton includes microscopic organisms (phytoplankton and zooplankton) that drift in water.'),
('nature', 3, 'What is the approximate speed at which tectonic plates move?', 'A few centimeters per year', ARRAY['A few meters per year', 'A few millimeters per century', 'A few kilometers per year'], 'en', true, 'Tectonic plates move at an average of 2 to 10 centimeters per year.'),
('nature', 3, 'What is a lake formed in a volcanic crater called?', 'A crater lake', ARRAY['A glacial lake', 'A tectonic lake', 'A dam lake'], 'en', true, 'A crater lake forms when water accumulates in the depression left by a volcanic crater.'),
('nature', 3, 'What percentage of Earth''s water is fresh water?', 'About 3%', ARRAY['About 10%', 'About 25%', 'About 50%'], 'en', true, 'Only about 3% of Earth''s water is fresh water, and much of it is locked in glaciers.'),
('nature', 3, 'What is the most explosive type of volcanic eruption?', 'Plinian eruption', ARRAY['Hawaiian eruption', 'Strombolian eruption', 'Effusive eruption'], 'en', true, 'Plinian eruptions are characterized by violent explosions and ash columns that can reach 45 km high.'),
('nature', 3, 'What is the main environmental function of wetlands?', 'Filtering and purifying water', ARRAY['Producing oxygen', 'Regulating tides', 'Storing methane'], 'en', true, 'Wetlands act as natural filters and sponges that also help regulate flooding.'),
('nature', 3, 'What type of ecological succession occurs after a forest fire?', 'Secondary succession', ARRAY['Primary succession', 'Climax stage', 'Regression'], 'en', true, 'Secondary succession occurs on previously colonized substrate that has been disturbed, such as after a fire.'),
('nature', 3, 'What is the name of the major geological fault in California?', 'The San Andreas Fault', ARRAY['The Rift Fault', 'The Hayward Fault', 'The Pacific Fault'], 'en', true, 'The San Andreas Fault is a 1,300 km transform fault between the Pacific and North American plates.'),
('nature', 3, 'At what altitude do cirrus clouds typically form?', 'Above 6,000 meters', ARRAY['Below 2,000 meters', 'Between 2,000 and 4,000 meters', 'At sea level'], 'en', true, 'Cirrus clouds are high-altitude clouds composed of ice crystals.'),
('nature', 3, 'What causes coral bleaching?', 'Expulsion of symbiotic algae due to heat stress', ARRAY['Ocean pollution only', 'Predation by fish', 'Cold water temperatures'], 'en', true, 'Coral bleaching occurs when corals expel their symbiotic algae (zooxanthellae) due to thermal stress.'),
('nature', 3, 'What is the largest river delta in the world?', 'The Ganges-Brahmaputra Delta', ARRAY['The Nile Delta', 'The Mississippi Delta', 'The Mekong Delta'], 'en', true, 'The Ganges-Brahmaputra Delta in Bangladesh covers approximately 105,000 square kilometers.'),
('nature', 3, 'What unique property of water makes ice float?', 'Water is denser as a liquid than as a solid', ARRAY['Ice is made of different molecules', 'Ice contains air bubbles', 'Water expands when heated'], 'en', true, 'Ice floats because water is densest at 4°C, a property essential for aquatic life.'),
('nature', 3, 'What is the process of rock transformation under pressure and heat called?', 'Metamorphism', ARRAY['Diagenesis', 'Weathering', 'Melting'], 'en', true, 'Metamorphism transforms existing rocks without melting them, creating metamorphic rocks.'),
('nature', 3, 'What gas is released by decomposing organic matter in marshes?', 'Methane', ARRAY['Oxygen', 'Nitrogen', 'Helium'], 'en', true, 'Methane (CH4) is produced by methanogenic bacteria during anaerobic decomposition.'),
('nature', 3, 'What is the intertidal zone between high and low tide called?', 'The littoral zone (foreshore)', ARRAY['The continental shelf', 'The abyssal zone', 'The pelagic zone'], 'en', true, 'The littoral or intertidal zone is alternately exposed and submerged by tides.'),
('nature', 3, 'What atmospheric phenomenon creates wind?', 'Differences in air pressure', ARRAY['Earth''s rotation alone', 'Lunar gravity', 'Ocean currents'], 'en', true, 'Wind is created by air moving from areas of high pressure to areas of low pressure.'),
('nature', 3, 'What is special about Lake Baikal in Russia?', 'It is the deepest lake in the world', ARRAY['It is the largest lake in the world', 'It is the saltiest lake in the world', 'It is the warmest lake in the world'], 'en', true, 'Lake Baikal reaches 1,642 meters deep and contains about 20% of the world''s unfrozen fresh water.'),
('nature', 3, 'What layer of the Earth lies between the crust and the core?', 'The mantle', ARRAY['The asthenosphere only', 'The lithosphere', 'The mesosphere'], 'en', true, 'The Earth''s mantle makes up about 84% of Earth''s volume, located between the crust and core.'),
('nature', 3, 'What is the main factor that determines a region''s climate?', 'Latitude', ARRAY['Longitude', 'Altitude only', 'Vegetation'], 'en', true, 'Latitude is the primary climate factor because it determines the angle of incoming solar radiation.'),
('nature', 3, 'What metal is extracted from bauxite?', 'Aluminum', ARRAY['Copper', 'Iron', 'Zinc'], 'en', true, 'Bauxite is the primary ore used to produce aluminum through an electrolytic process.'),
('nature', 3, 'What is the difference between a stalactite and a stalagmite?', 'Stalactites hang from the ceiling, stalagmites rise from the floor', ARRAY['Stalactites are larger', 'Stalagmites are only limestone', 'Stalactites are hollow'], 'en', true, 'Stalactites hang from the ceiling (they hold tight) and stalagmites grow up from the floor (they might reach the ceiling).'),
('nature', 3, 'What is the main cause of deforestation in the Amazon?', 'Cattle ranching', ARRAY['Mining', 'Road building', 'Tourism'], 'en', true, 'Cattle ranching is the leading cause of Amazon deforestation, responsible for about 80% of cleared areas.'),
('nature', 3, 'What phenomenon causes magnetic pole reversals on Earth?', 'Movements in the liquid outer core', ARRAY['Solar storms', 'Earth''s rotation', 'Tides'], 'en', true, 'Magnetic reversals are caused by convection movements of liquid iron in the Earth''s outer core.'),
('nature', 3, 'What is the collection of all plant species in a region called?', 'Flora', ARRAY['Fauna', 'Biocenosis', 'Biota'], 'en', true, 'Flora refers to all the plant species present in a given geographic area.'),
('nature', 3, 'What role do coral reefs play for marine ecosystems?', 'They provide habitat and protection for 25% of marine species', ARRAY['They produce oxygen only', 'They filter salt from water', 'They regulate ocean temperature'], 'en', true, 'Coral reefs harbor about one quarter of all known marine species.'),
('nature', 3, 'What is formed when minerals are deposited as sea water evaporates?', 'Evaporite rocks', ARRAY['Igneous rocks', 'Metamorphic rocks', 'Organic rocks'], 'en', true, 'Evaporites are sedimentary rocks formed by the evaporation of water and deposition of dissolved salts.'),
('nature', 3, 'What is the nitrogen cycle in nature?', 'The biogeochemical cycling of nitrogen between atmosphere, soil, and organisms', ARRAY['The phosphorus cycle', 'The sulfur cycle', 'The carbon cycle'], 'en', true, 'The nitrogen cycle includes fixation, nitrification, denitrification, and ammonification.'),
('nature', 3, 'What type of ecological relationship is shown by clownfish and sea anemones?', 'Mutualism', ARRAY['Parasitism', 'Commensalism', 'Competition'], 'en', true, 'Clownfish and anemones have a mutualistic relationship where both species benefit from the partnership.'),
('nature', 3, 'What is the process by which sediment is deposited at a river mouth called?', 'Delta formation (deposition)', ARRAY['Erosion', 'Subduction', 'Weathering'], 'en', true, 'Deltas form when rivers slow down at their mouths and deposit the sediment they carry.'),
('nature', 3, 'What causes the seasons on Earth?', 'The tilt of Earth''s axis relative to its orbit', ARRAY['Distance from the Sun', 'The Moon''s gravity', 'Ocean currents'], 'en', true, 'Earth''s 23.5-degree axial tilt causes different parts of the planet to receive varying amounts of sunlight throughout the year.'),
('nature', 3, 'What is the phenomenon of land sinking due to groundwater extraction called?', 'Land subsidence', ARRAY['Erosion', 'Plate tectonics', 'Landslide'], 'en', true, 'Land subsidence occurs when large amounts of groundwater are pumped out, causing the ground above to sink.');
